// Sound lab S7 Speaker.  uv run pio run -d labs/sound-lab-s7 -e sound-lab-s7 -t upload
// The board makes sound. Numbers go out over I2S to the MAX98357A, a class-D amplifier: it switches
// the speaker fully on and off ~300 000 times a second, and how long each pulse lasts follows the
// number. The speaker cone is too slow to follow the switching, so it moves with the average: the
// wave. Efficient (little heat), and no analog wire anywhere on our side.
//
// What you hear is drawn on the screen:
//   wave      one note's waveform and its spectrum. Same note, different wave = different timbre:
//             a sine is one frequency, a square only the odd harmonics (1, 3, 5...), a saw all of
//             them. At 16 000 samples a second nothing above 8 kHz exists (Nyquist), so a square or
//             saw's high harmonics fold back down as wrong frequencies ("aliasing"): a slight grit
//             on high notes. Honest limit of this simple synth.
//   keys      two octaves; the notes light while they sound
//   envelope  ADSR: attack, decay, sustain, release. A note that starts or stops at full height
//             makes the cone jump: a click. The envelope fades it in and out.
//   tunes     melodies, scrolling like a piano roll
//   fx        game sounds made from recipes: sweeps, noise, filters
//
// Wiring: MAX98357A VIN -> 5V, GND -> GND, BCLK -> 39, LRC -> 38, DIN -> 47; the speaker on its screw
// terminal (the JST plug's two wires; red to +). GAIN and SD unconnected. The screen from lesson 03.
// Start quiet: `vol 20`. Volume is squared (50 = a quarter of the power of 100), like your ears like it.
//
// Views: wave · keys · envelope · tunes · fx   (click = next view, double-click = the action in the footer)
// Keys: double-click = the next note of the scale, long press = the next chord.
// Tunes and fx: double-click = play, long press = pick the next one.
#include <esp_heap_caps.h>

#include "sound_lab.h"
#include "sounds.h"
#include "spectrum.h"

namespace {

// ---- State ------------------------------------------------------------------------------------

struct Synth {
  syn::Wave wave = syn::Wave::Triangle;
  syn::Envelope env;
  int bpm = 120;
  float lastHz = 440;
} cfg;

// Two render buffers in PSRAM, used in turn: the speaker may still read the old one for a block
// while we write the new one.
constexpr uint32_t kCap = uint32_t(s7::kRate * 30);  // 30 s
int16_t *bufs[2] = {nullptr, nullptr};
int which = 0;

constexpr int kMaxEvents = 160;
struct Piece {
  s7::Event ev[kMaxEvents];
  int count = 0;
  uint32_t totalMs = 0;
  uint32_t startedAt = 0;  // millis() when it started playing
  bool playing = false;
  char title[24] = "";
  const int16_t *samples = nullptr;
  uint32_t n = 0;
} piece;

int scaleStep = 0, chordStep = 0, tuneIdx = 0, fxIdx = 0;

struct TuneDef {
  const char *name;
  const char *notes;
  int bpm;
};
const TuneDef kTunes[] = {
    {"twinkle", "C5/4 C5/4 G5/4 G5/4 A5/4 A5/4 G5/2 F5/4 F5/4 E5/4 E5/4 D5/4 D5/4 C5/2", 150},
    {"ode", "E5/4 E5/4 F5/4 G5/4 G5/4 F5/4 E5/4 D5/4 C5/4 C5/4 D5/4 E5/4 E5/4. D5/8 D5/2", 150},
    {"happy", "C5/8. C5/16 D5/4 C5/4 F5/4 E5/2 C5/8. C5/16 D5/4 C5/4 G5/4 F5/2 C5/8. C5/16 C6/4 A5/4 F5/4 E5/4 D5/4 Bb5/8. Bb5/16 A5/4 F5/4 G5/4 F5/2", 120},
    {"korobeiniki", "E5/4 B4/8 C5/8 D5/4 C5/8 B4/8 A4/4 A4/8 C5/8 E5/4 D5/8 C5/8 B4/4. C5/8 D5/4 E5/4 C5/4 A4/4 A4/2 r/8 D5/4. F5/8 A5/4 G5/8 F5/8 E5/4. C5/8 E5/4 D5/8 C5/8 B4/4 B4/8 C5/8 D5/4 E5/4 C5/4 A4/4 A4/2", 150},
    {"scale", "C4/8 D4/8 E4/8 F4/8 G4/8 A4/8 B4/8 C5/8 D5/8 E5/8 F5/8 G5/8 A5/8 B5/8 C6/4", 160},
    {"arpeggio", "C4/16 E4/16 G4/16 C5/16 E5/16 G5/16 C6/8 G5/16 E5/16 C5/16 G4/16 E4/16 C4/4 F4/16 A4/16 C5/16 F5/16 A5/16 C6/16 F6/8", 110},
};
constexpr int kTuneCount = sizeof(kTunes) / sizeof(kTunes[0]);
const char *const kChords[] = {"Cmaj", "Fmaj", "Gmaj", "Am", "Dm", "G7"};
const int kScale[] = {60, 62, 64, 65, 67, 69, 71, 72, 74, 76, 77, 79, 81, 83};  // C major, C4-B5

const char *noteName(int midi, char *out, size_t len) {
  static const char *const kNames[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
  snprintf(out, len, "%s%d", kNames[((midi % 12) + 12) % 12], midi / 12 - 1);
  return out;
}

// ---- Rendering and playing ---------------------------------------------------------------------

int16_t *fresh() {
  which ^= 1;
  std::fill_n(bufs[which], kCap, int16_t(0));
  return bufs[which];
}

void start(SoundLab &lab, int16_t *b, uint32_t n, const char *title) {
  lab.speaker().stop();
  lab.speaker().play(b, n);
  piece.samples = b, piece.n = n;
  piece.totalMs = n * 1000 / uint32_t(s7::kRate);
  piece.startedAt = millis();
  piece.playing = true;
  strlcpy(piece.title, title, sizeof(piece.title));
}

// Notes one after another (hz, ms pairs from a Tune), each with the current wave and envelope.
void playTune(SoundLab &lab, const char *notes, int bpm, const char *title) {
  int16_t *b = fresh();
  syn::Tune t;
  t.set(notes, bpm);
  float hz = 0, ms = 0;
  uint32_t atMs = 0, end = 0;
  piece.count = 0;
  while (t.next(hz, ms)) {
    if (hz > 0) {
      const uint32_t at = uint32_t(atMs * s7::kRate / 1000);
      if (at >= kCap) break;
      end = std::max(end, s7::renderNote(b, kCap, at, hz, ms * 0.95f, cfg.wave, cfg.env, 0.55f));
      if (piece.count < kMaxEvents) piece.ev[piece.count++] = {atMs, uint32_t(ms), s7::midiOf(hz)};
      cfg.lastHz = hz;
    }
    atMs += uint32_t(ms);
  }
  start(lab, b, std::max(end, uint32_t(atMs * s7::kRate / 1000)), title);
}

// Several notes at once.
void playChord(SoundLab &lab, const int *midis, int n, uint32_t ms, const char *title) {
  int16_t *b = fresh();
  piece.count = 0;
  uint32_t end = 0;
  for (int i = 0; i < n; i++) {
    // Each voice a bit quieter, so three together don't clip: 1/sqrt(n) keeps the loudness even.
    end = std::max(end, s7::renderNote(b, kCap, 0, s7::hzOf(midis[i]), float(ms), cfg.wave, cfg.env, 0.7f / sqrtf(float(n))));
    piece.ev[piece.count++] = {0, ms, midis[i]};
  }
  cfg.lastHz = s7::hzOf(midis[0]);
  start(lab, b, end, title);
}

void playNote(SoundLab &lab, float hz, uint32_t ms) {
  int16_t *b = fresh();
  const uint32_t end = s7::renderNote(b, kCap, 0, hz, float(ms), cfg.wave, cfg.env, 0.7f);
  piece.count = 0;
  piece.ev[piece.count++] = {0, ms, s7::midiOf(hz)};
  cfg.lastHz = hz;
  char t[24];
  snprintf(t, sizeof(t), "%.0f Hz", hz);
  start(lab, b, end, t);
}

void playFx(SoundLab &lab, int idx) {
  int count = 0;
  const s7::Fx *fx = s7::effects(count);
  fxIdx = (idx % count + count) % count;
  int16_t *b = fresh();
  const uint32_t n = fx[fxIdx].render(b, kCap);
  piece.count = 0;
  start(lab, b, n, fx[fxIdx].name);
  lab.note(sv::Note::Info, "fx %s: %s", fx[fxIdx].name, fx[fxIdx].what);
}

uint32_t elapsedMs() { return piece.playing ? millis() - piece.startedAt : 0; }

// ---- Views ------------------------------------------------------------------------------------

// The wave view's picture: one steady stretch of the current note, and its spectrum.
struct WavePic {
  int16_t s[512];
  float bins[256];
  syn::Wave wave = syn::Wave(255);
  float hz = 0;
} pic;
snd::Fft fft;

void renderPic() {
  if (pic.wave == cfg.wave && pic.hz == cfg.lastHz) return;
  pic.wave = cfg.wave, pic.hz = cfg.lastHz;
  syn::Voice v;
  syn::Envelope flat;
  flat.attackMs = 0.1f, flat.decayMs = 0.1f, flat.sustain = 1;
  v.start(cfg.lastHz, 1000, cfg.wave, flat, s7::kRate, 0.9f);
  for (int i = 0; i < 64; i++) v.next();  // past the (tiny) attack
  for (int i = 0; i < 512; i++) pic.s[i] = int16_t(v.next() * 30000);
  fft.run(pic.s);
  for (int k = 0; k < 256; k++) pic.bins[k] = fft.db(k);
}

void drawWave(SoundLab &, FrameBuffer &fb, float) {
  renderPic();
  // Top: four periods of the wave (or 10 ms of noise).
  const int periods = cfg.wave == syn::Wave::Noise ? 0 : 4;
  const int span = periods ? std::min(512, int(periods * s7::kRate / cfg.lastHz)) : 160;
  sv::wave(fb, 10, sv::kTop + 4, 300, 56, pic.s, std::max(span, 8), 32000, sv::kSound);
  char text[48];
  char nn[16];
  snprintf(text, sizeof(text), "%s  %.0f Hz (%s)", syn::waveName(cfg.wave), cfg.lastHz, noteName(s7::midiOf(cfg.lastHz), nn, sizeof(nn)));
  sv::small(fb, 10, sv::kTop + 62, pal::ink, text);
  // Bottom: the spectrum 0-8 kHz, one column per bin pair; harmonics stand up as lines.
  const int x0 = 10, y0 = sv::kTop + 74, h = 46, w = 300;
  for (int col = 0; col < w; col++) {
    const int k0 = col * 256 / w, k1 = std::max(k0 + 1, (col + 1) * 256 / w);
    float m = -120;
    for (int k = k0; k < k1; k++) m = std::max(m, pic.bins[k]);
    const int bh = std::max(0, std::min(h, int((m + 60) * h / 60)));  // -60..0 dB
    if (bh) fb.drawFastVLine(x0 + col, y0 + h - bh, bh, mix(sv::kSound, pal::amber, uint8_t(col * 255 / w)));
  }
  fb.drawFastHLine(x0, y0 + h, w, pal::dim);
  sv::small(fb, x0, y0 + h + 3, pal::muted, "0");
  sv::small(fb, x0 + w / 2 - 6, y0 + h + 3, pal::muted, "4k");
  sv::small(fb, x0 + w - 18, y0 + h + 3, pal::muted, "8kHz");
  const char *why = cfg.wave == syn::Wave::Sine       ? "one frequency: pure"
                    : cfg.wave == syn::Wave::Square   ? "odd harmonics 1,3,5..: hollow"
                    : cfg.wave == syn::Wave::Triangle ? "odd harmonics, soft: flute"
                    : cfg.wave == syn::Wave::Saw      ? "every harmonic: bright, buzzy"
                                                      : "every frequency: hiss";
  sv::small(fb, 120, y0 + h + 3, pal::muted, why);
}

// Keys C4..B5: 14 white keys, 10 black.
void drawKeys(SoundLab &, FrameBuffer &fb, float) {
  bool lit[128] = {};
  const uint32_t e = elapsedMs();
  if (piece.playing)
    for (int i = 0; i < piece.count; i++)
      if (e >= piece.ev[i].startMs && e < piece.ev[i].startMs + piece.ev[i].durMs && piece.ev[i].midi >= 0 && piece.ev[i].midi < 128)
        lit[piece.ev[i].midi] = true;
  const int x0 = 13, y0 = sv::kTop + 18, kw = 21, kh = 80;
  const int whiteSemis[] = {0, 2, 4, 5, 7, 9, 11};
  for (int i = 0; i < 14; i++) {
    const int midi = 60 + (i / 7) * 12 + whiteSemis[i % 7];
    const int x = x0 + i * kw;
    fb.fillRect(x, y0, kw - 2, kh, lit[midi] ? sv::kSound : pal::ink);
    if (i % 7 == 0) {
      char t[6];
      snprintf(t, sizeof(t), "C%d", 4 + i / 7);
      sv::small(fb, x + 4, y0 + kh - 10, pal::night, t);
    }
  }
  const int blackAfter[] = {0, 1, 3, 4, 5};  // black keys sit after C, D, F, G, A
  const int blackSemis[] = {1, 3, 6, 8, 10};
  for (int o = 0; o < 2; o++)
    for (int j = 0; j < 5; j++) {
      const int midi = 60 + o * 12 + blackSemis[j];
      const int x = x0 + (o * 7 + blackAfter[j]) * kw + kw - 7;
      fb.fillRect(x, y0, 12, kh * 6 / 10, lit[midi] ? sv::kSound : pal::night);
    }
  char text[64];
  snprintf(text, sizeof(text), "%s - A%.0f D%.0f S%.0f%% R%.0f ms", syn::waveName(cfg.wave), cfg.env.attackMs, cfg.env.decayMs, cfg.env.sustain * 100,
           cfg.env.releaseMs);
  sv::small(fb, 10, sv::kTop + 4, pal::muted, text);
  sv::small(fb, 10, sv::kTop + 104, pal::muted, "2x: next note   long: next chord");
  if (piece.playing) sv::small(fb, 220, sv::kTop + 104, sv::kSound, piece.title);
}

void drawEnvelope(SoundLab &, FrameBuffer &fb, float) {
  const syn::Envelope &e = cfg.env;
  const float holdMs = 250;
  const float total = e.attackMs + e.decayMs + holdMs + e.releaseMs;
  const int x0 = 14, y0 = sv::kTop + 14, w = 292, h = 84;
  auto X = [&](float ms) { return x0 + int(ms / total * w); };
  auto Y = [&](float a) { return y0 + h - int(a * h); };
  const float pts[5][2] = {{0, 0}, {e.attackMs, 1}, {e.attackMs + e.decayMs, e.sustain}, {e.attackMs + e.decayMs + holdMs, e.sustain}, {total, 0}};
  fb.drawFastHLine(x0, y0 + h, w, pal::dim);
  const uint16_t colours[4] = {pal::teal, pal::amber, sv::kSound, pal::coral};
  const char *labels[4] = {"A", "D", "S", "R"};
  for (int i = 0; i < 4; i++) {
    for (int dy = 0; dy < 2; dy++) fb.drawLine(X(pts[i][0]), Y(pts[i][1]) + dy, X(pts[i + 1][0]), Y(pts[i + 1][1]) + dy, colours[i]);
    sv::small(fb, (X(pts[i][0]) + X(pts[i + 1][0])) / 2 - 2, y0 + h + 4, colours[i], labels[i]);
  }
  // The dot rides the curve while a note plays: attack, decay, sustain while held, then release.
  if (piece.playing && piece.count == 1) {
    const float t = float(elapsedMs());
    const float held = float(piece.ev[0].durMs) - e.releaseMs;
    float ms, a;
    if (t < e.attackMs) ms = t, a = t / e.attackMs;
    else if (t < e.attackMs + e.decayMs) ms = t, a = 1 - (1 - e.sustain) * (t - e.attackMs) / e.decayMs;
    else if (t < held) ms = std::min(t, e.attackMs + e.decayMs + holdMs * 0.99f), a = e.sustain;
    else ms = e.attackMs + e.decayMs + holdMs + (t - held), a = e.sustain * std::max(0.0f, 1 - (t - held) / e.releaseMs);
    fb.fillCircle(X(std::min(ms, total)), Y(a), 4, pal::ink);
  }
  char text[64];
  snprintf(text, sizeof(text), "adsr %.0f %.0f %.0f %.0f   (ms, ms, %%, ms)", e.attackMs, e.decayMs, e.sustain * 100, e.releaseMs);
  sv::small(fb, x0, sv::kTop + 112, pal::ink, text);
  sv::small(fb, x0, sv::kTop + 2, pal::muted, "fade in, fall, hold, fade out: no clicks");
}

void drawTunes(SoundLab &, FrameBuffer &fb, float) {
  // Left: the list.
  for (int i = 0; i < kTuneCount; i++) {
    const bool sel = i == tuneIdx;
    if (sel) fb.fillRect(4, sv::kTop + 4 + i * 16, 92, 15, sv::kPanel);
    sv::small(fb, 8, sv::kTop + 8 + i * 16, sel ? sv::kSound : pal::muted, kTunes[i].name);
  }
  sv::small(fb, 8, sv::kTop + 112, pal::muted, "2x: play");
  sv::small(fb, 8, sv::kTop + 122, pal::muted, "long: next");
  // Right: a piano roll of the playing tune (or the picked one, from the start). Pitch up, time right.
  const int x0 = 104, y0 = sv::kTop + 4, w = 210, h = 124;
  fb.drawRect(x0, y0, w, h, pal::dim);
  const bool live = piece.playing && strcmp(piece.title, kTunes[tuneIdx].name) == 0;
  // Not playing it? Parse the picked tune just for the picture (never touching what plays).
  static s7::Event preview[kMaxEvents];
  const s7::Event *ev = piece.ev;
  int count = piece.count;
  if (!live) {
    syn::Tune t;
    t.set(kTunes[tuneIdx].notes, kTunes[tuneIdx].bpm);
    float hz = 0, ms = 0;
    uint32_t at = 0;
    count = 0;
    while (t.next(hz, ms) && count < kMaxEvents) {
      if (hz > 0) preview[count++] = {at, uint32_t(ms), s7::midiOf(hz)};
      at += uint32_t(ms);
    }
    ev = preview;
  }
  int lo = 127, hi = 0;
  for (int i = 0; i < count; i++) lo = std::min(lo, ev[i].midi), hi = std::max(hi, ev[i].midi);
  if (hi < lo) return;
  lo -= 1, hi += 1;
  const uint32_t window = 4000;  // ms across the roll
  const uint32_t now = live ? elapsedMs() : 0;
  const int playX = x0 + w / 4;
  const float pxPerMs = float(w) / window;
  for (int i = 0; i < count; i++) {
    const s7::Event &e = ev[i];
    const int x = playX + int((float(e.startMs) - float(now)) * pxPerMs);
    const int len = std::max(2, int(e.durMs * pxPerMs) - 1);
    if (x + len < x0 + 1 || x > x0 + w - 2) continue;
    const int y = y0 + h - 4 - (e.midi - lo) * (h - 8) / std::max(1, hi - lo);
    const bool on = live && now >= e.startMs && now < e.startMs + e.durMs;
    const int xa = std::max(x, x0 + 1), xb = std::min(x + len, x0 + w - 2);
    fb.fillRect(xa, y - 2, xb - xa, 5, on ? pal::ink : mix(sv::kSound, pal::night, 60));
  }
  fb.drawFastVLine(playX, y0 + 1, h - 2, live ? pal::amber : pal::dim);
}

void drawFx(SoundLab &, FrameBuffer &fb, float) {
  int count = 0;
  const s7::Fx *fx = s7::effects(count);
  for (int i = 0; i < count; i++) {
    const bool sel = i == fxIdx;
    if (sel) fb.fillRect(4, sv::kTop + 4 + i * 16, 82, 15, sv::kPanel);
    sv::small(fb, 8, sv::kTop + 8 + i * 16, sel ? sv::kSound : pal::muted, fx[i].name);
  }
  // The last effect's whole waveform, with a playhead.
  const int x0 = 94, y0 = sv::kTop + 6, w = 218, h = 96;
  fb.drawRect(x0 - 1, y0 - 1, w + 2, h + 2, pal::dim);
  if (piece.samples && piece.count == 0 && piece.n) {
    sv::wave(fb, x0, y0, w, h, piece.samples, int(piece.n), 33000, sv::kSound);
    if (piece.playing) fb.drawFastVLine(x0 + int(std::min(1.0f, float(elapsedMs()) / std::max<uint32_t>(1, piece.totalMs)) * w), y0, h, pal::ink);
    char t[40];
    snprintf(t, sizeof(t), "%s, %lu ms", piece.title, static_cast<unsigned long>(piece.totalMs));
    sv::small(fb, x0, y0 + h + 5, pal::ink, t);
  } else {
    sv::small(fb, x0 + 10, y0 + h / 2 - 3, pal::muted, "double-click to play an effect");
  }
  sv::small(fb, x0, y0 + h + 17, pal::muted, fx[fxIdx].what);
}

const SoundView kViews[] = {
    {"wave", drawWave, "wave next"},
    {"keys", drawKeys, "next note"},
    {"envelope", drawEnvelope, "note A4 600"},
    {"tunes", drawTunes, "tune picked"},
    {"fx", drawFx, "fx picked"},
};

// ---- Commands ---------------------------------------------------------------------------------

void cmdWave(SoundLab &lab, const String &, const String &lower) {
  syn::Wave w;
  if (lower == "next") w = syn::Wave((int(cfg.wave) + 1) % 5);
  else if (!syn::parseWave(lower.c_str(), w)) return lab.warn("wave sine | square | triangle | saw | noise | next");
  cfg.wave = w;
  playNote(lab, cfg.lastHz, 500);
  lab.note(sv::Note::Info, "wave %s", syn::waveName(w));
}

// "play C4 E4 G4" or with lengths "play C4/8 E4/8 G4/2": one after another at the current bpm.
void cmdPlay(SoundLab &lab, const String &arg, const String &) {
  if (arg.isEmpty()) return lab.warn("play <notes>, e.g. play C4 E4 G4 C5/2   (/4 = quarter, /8 = eighth, r = rest)");
  static char text[200];
  strlcpy(text, arg.c_str(), sizeof(text));
  playTune(lab, text, cfg.bpm, "play");
}

void cmdChord(SoundLab &lab, const String &arg, const String &) {
  int m[4];
  const int n = s7::chordNotes(arg.c_str(), m);
  if (!n) return lab.warn("chord <root><quality>: Cmaj Am G7 Fmaj7 Dm7 Bdim Caug Dsus4 Esus2 (root may have # or b)");
  playChord(lab, m, n, 1200, arg.c_str());
  char a[16], b[16], c[16];
  lab.note(sv::Note::Info, "%s = %s %s %s%s", arg.c_str(), noteName(m[0], a, 16), noteName(m[1], b, 16), noteName(m[2], c, 16), n > 3 ? " +7th" : "");
}

void cmdNote(SoundLab &lab, const String &arg, const String &) {
  const int sp = arg.indexOf(' ');
  const String what = sp < 0 ? arg : arg.substring(0, sp);
  long ms = 600;
  if (sp > 0 && !SoundLab::number(arg.substring(sp + 1), 20, 10000, ms)) return lab.warn("note <name|Hz> [ms 20-10000]");
  float hz = syn::noteHz(what.c_str());
  if (hz <= 0 && !SoundLab::decimal(what, 20, 8000, hz)) return lab.warn("note A4 | note C#5 300 | note 1000");
  if (hz > 7000) lab.note(sv::Note::Warn, "close to 8 kHz: the limit at 16 kHz");
  playNote(lab, hz, uint32_t(ms));
}

void cmdAdsr(SoundLab &lab, const String &arg, const String &) {
  float v[4];
  int n = 0, from = 0;
  while (n < 4 && from <= int(arg.length())) {
    int sp = arg.indexOf(' ', from);
    if (sp < 0) sp = arg.length();
    if (sp > from && !SoundLab::decimal(arg.substring(from, sp), 0, 5000, v[n++])) n = -10;
    from = sp + 1;
  }
  if (n != 4 || v[2] > 100) {
    lab.warn("adsr <attack ms> <decay ms> <sustain %%> <release ms>, e.g. adsr 5 80 65 90 (a plucked string: adsr 1 300 0 50)");
    return;
  }
  cfg.env.attackMs = std::max(0.5f, v[0]);
  cfg.env.decayMs = std::max(0.5f, v[1]);
  cfg.env.sustain = v[2] / 100.0f;
  cfg.env.releaseMs = std::max(1.0f, v[3]);
  lab.showView("envelope");
  playNote(lab, cfg.lastHz, 600);
}

void cmdTune(SoundLab &lab, const String &, const String &lower) {
  if (lower == "picked") return playTune(lab, kTunes[tuneIdx].notes, kTunes[tuneIdx].bpm, kTunes[tuneIdx].name);
  for (int i = 0; i < kTuneCount; i++)
    if (lower == kTunes[i].name) {
      tuneIdx = i;
      lab.showView("tunes");
      return playTune(lab, kTunes[i].notes, kTunes[i].bpm, kTunes[i].name);
    }
  Serial.print("tunes:");
  for (const TuneDef &t : kTunes) Serial.printf(" %s", t.name);
  Serial.println();
  if (!lower.isEmpty()) lab.warn("no tune '%s'", lower.c_str());
}

void cmdBpm(SoundLab &lab, const String &arg, const String &) {
  long b = 0;
  if (!SoundLab::number(arg, 30, 300, b)) return lab.warn("bpm <30-300> (now %d): the tempo for play", cfg.bpm);
  cfg.bpm = int(b);
}

void cmdFx(SoundLab &lab, const String &, const String &lower) {
  int count = 0;
  const s7::Fx *fx = s7::effects(count);
  if (lower == "picked") return playFx(lab, fxIdx);
  for (int i = 0; i < count; i++)
    if (lower == fx[i].name) {
      lab.showView("fx");
      return playFx(lab, i);
    }
  Serial.print("effects:");
  for (int i = 0; i < count; i++) Serial.printf(" %s", fx[i].name);
  Serial.println();
}

void cmdStop(SoundLab &lab, const String &, const String &) {
  lab.speaker().stop();
  piece.playing = false;
}

void cmdNextNote(SoundLab &lab, const String &, const String &) {
  const int midi = kScale[scaleStep++ % 14];
  playNote(lab, s7::hzOf(midi), 450);
}

const SoundCommand kCommands[] = {
    {"wave", "<name|next>", "sine square triangle saw noise: the timbre", cmdWave},
    {"play", "<notes>", "notes one after another: play C4 E4 G4/2 r/4 C5", cmdPlay},
    {"chord", "<name>", "notes together: Cmaj Am G7 Fmaj7 Bdim Dsus4", cmdChord},
    {"note", "<name|Hz> [ms]", "one note: note A4, note 1000 250", cmdNote},
    {"adsr", "<a> <d> <s%> <r>", "the envelope, ms ms % ms (default 6 80 65 90)", cmdAdsr},
    {"tune", "<name>", "twinkle ode happy korobeiniki scale arpeggio", cmdTune},
    {"bpm", "<n>", "tempo for play (default 120)", cmdBpm},
    {"fx", "<name>", "laser coin jump powerup explosion siren modem", cmdFx},
    {"stop", "", "silence", cmdStop},
    {"next", "", "the next note of the C major scale", cmdNextNote},
};

// ---- Hooks ------------------------------------------------------------------------------------

void setup(SoundLab &lab) {
  for (int i = 0; i < 2; i++) bufs[i] = static_cast<int16_t *>(heap_caps_calloc(kCap, sizeof(int16_t), MALLOC_CAP_SPIRAM));
  if (!bufs[0] || !bufs[1]) log_e("S7: no PSRAM for the render buffers");
  fft.setSize(512);
  lab.note(sv::Note::Info, "start quiet: vol 20, then raise it");
}

void tick(SoundLab &lab) {
  if (piece.playing && !lab.speaker().playing() && elapsedMs() > piece.totalMs) piece.playing = false;
}

bool gesture(SoundLab &lab, Gesture g, bool) {
  const char *v = lab.spec().views[lab.view()].name;
  if (g == Gesture::DoubleClick && strcmp(v, "keys") == 0) return cmdNextNote(lab, "", ""), true;
  if (g == Gesture::LongPress && strcmp(v, "keys") == 0) {
    int m[4];
    const char *name = kChords[chordStep++ % (sizeof(kChords) / sizeof(kChords[0]))];
    playChord(lab, m, s7::chordNotes(name, m), 1000, name);
    return true;
  }
  if (g == Gesture::LongPress && strcmp(v, "tunes") == 0) return tuneIdx = (tuneIdx + 1) % kTuneCount, true;
  if (g == Gesture::LongPress && strcmp(v, "fx") == 0) {
    int count = 0;
    s7::effects(count);
    fxIdx = (fxIdx + 1) % count;
    return true;
  }
  return false;
}

const SoundLabSpec kSpec{
    "sound-lab-s7", "S7", "Speaker", kViews, sizeof(kViews) / sizeof(kViews[0]), 0,
    kCommands, sizeof(kCommands) / sizeof(kCommands[0]), setup, nullptr, tick, gesture, "stop",
};

SoundLab lab(kSpec);

}  // namespace

void setup() { lab.begin(); }

void loop() { lab.loop(); }

// S7's sound factory: notes, chords and effects rendered into a buffer of 16-bit samples, which the
// speaker then plays (speaker.play). Rendering ahead instead of live lets us play chords (the
// speaker's own synth has one voice) and draw exactly what you hear. Pure C++, no Arduino.
//
// Effects are "procedural": no recordings, only recipes. A frequency that glides (a sweep), noise
// that gets darker (a low-pass filter closing), a pitch that wobbles (a siren). The classic 8-bit
// game sounds are all made this way.
#pragma once

#include <math.h>
#include <stdint.h>
#include <string.h>

#include <algorithm>

#include "synth.h"

namespace s7 {

constexpr float kRate = 16000;
constexpr float kTau = 6.2831853f;

inline int16_t toSample(float v) { return int16_t(syn::softClip(v) * 32000.0f); }

// Add a float sample onto an int16 buffer without wrapping around.
inline void addInto(int16_t &dst, float v) {
  const float s = dst + v * 32000.0f;
  dst = int16_t(s > 32767 ? 32767 : s < -32768 ? -32768 : s);
}

inline int midiOf(float hz) { return hz > 0 ? int(lroundf(69 + 12 * log2f(hz / 440.0f))) : -1; }
inline float hzOf(int midi) { return 440.0f * powf(2.0f, (midi - 69) / 12.0f); }

// One sounding note in a rendered piece: for lighting keys and drawing the piano roll.
struct Event {
  uint32_t startMs, durMs;
  int midi;
};

// "Cmaj", "Am", "G7", "F#m7", "Bbdim", "Dsus4": root (octave 4) + quality. Returns the note count.
inline int chordNotes(const char *name, int midis[4]) {
  static const int kSemis[] = {9, 11, 0, 2, 4, 5, 7};
  if (!name || name[0] < 'A' || name[0] > 'G') return 0;
  int root = 60 + kSemis[name[0] - 'A'], i = 1;
  if (name[i] == '#') root++, i++;
  else if (name[i] == 'b') root--, i++;
  const char *q = name + i;
  static const struct {
    const char *q;
    int n, iv[4];
  } kQualities[] = {
      {"", 3, {0, 4, 7}},      {"maj", 3, {0, 4, 7}},   {"m", 3, {0, 3, 7}},      {"min", 3, {0, 3, 7}},
      {"7", 4, {0, 4, 7, 10}}, {"maj7", 4, {0, 4, 7, 11}}, {"m7", 4, {0, 3, 7, 10}}, {"dim", 3, {0, 3, 6}},
      {"aug", 3, {0, 4, 8}},   {"sus4", 3, {0, 5, 7}},  {"sus2", 3, {0, 2, 7}},
  };
  for (const auto &k : kQualities)
    if (strcmp(q, k.q) == 0) {
      for (int j = 0; j < k.n; j++) midis[j] = root + k.iv[j];
      return k.n;
    }
  return 0;
}

// Render one note (adding onto whatever is already there) starting at sample `at`.
inline uint32_t renderNote(int16_t *buf, uint32_t cap, uint32_t at, float hz, float ms, syn::Wave w, const syn::Envelope &env,
                           float level) {
  syn::Voice v;
  v.start(hz, std::max(1.0f, ms - env.releaseMs), w, env, kRate, level);
  uint32_t i = at;
  while (v.active() && i < cap) addInto(buf[i++], v.next());
  return i;
}

// ---- Effects ---------------------------------------------------------------------------------

struct Fx {
  const char *name;
  const char *what;
  uint32_t (*render)(int16_t *buf, uint32_t cap);
};

inline float square(float phase) { return phase - floorf(phase) < 0.5f ? 1.0f : -1.0f; }

struct Noise {
  uint32_t s = 12345;
  float next() {
    s = s * 1664525u + 1013904223u;
    return (int32_t(s) >> 8) / 8388608.0f;
  }
};

// Laser: a square wave diving from 2.4 kHz to 150 Hz in a third of a second.
inline uint32_t laser(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(0.35f * kRate));
  float ph = 0;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    ph += (2400 * expf(-t * 9) + 150) / kRate;
    b[i] = toSample(square(ph) * 0.35f * (1 - t / 0.35f));
  }
  return n;
}

// Coin: two square notes, B5 then E6, the second one ringing out.
inline uint32_t coin(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(0.42f * kRate));
  float ph = 0;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    ph += (t < 0.07f ? 987.8f : 1318.5f) / kRate;
    b[i] = toSample(square(ph) * 0.3f * (t < 0.07f ? 1 : expf(-(t - 0.07f) * 8)));
  }
  return n;
}

// Jump: a quick upward glide.
inline uint32_t jump(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(0.22f * kRate));
  float ph = 0;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    ph += (250 + 650 * t / 0.22f) / kRate;
    b[i] = toSample(square(ph) * 0.3f * (1 - 0.6f * t / 0.22f));
  }
  return n;
}

// Power-up: three rising arpeggios, each a step higher.
inline uint32_t powerUp(int16_t *b, uint32_t cap) {
  syn::Envelope env;
  env.attackMs = 2, env.decayMs = 10, env.sustain = 0.8f, env.releaseMs = 10;
  std::fill_n(b, cap, int16_t(0));
  uint32_t end = 0;
  const int arp[] = {0, 4, 7, 12};
  for (int round = 0; round < 3; round++)
    for (int k = 0; k < 4; k++) {
      const uint32_t at = uint32_t((round * 4 + k) * 0.045f * kRate);
      end = std::max(end, renderNote(b, cap, at, hzOf(72 + round * 2 + arp[k]), 50, syn::Wave::Triangle, env, 0.5f));
    }
  return end;
}

// Explosion: noise through a low-pass filter that closes (darker and darker) while it fades.
inline uint32_t explosion(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(0.9f * kRate));
  Noise noise;
  float lp = 0, ph = 0;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    const float cutoff = 0.5f * expf(-t * 4) + 0.01f;  // the filter's "how fast it follows" 0-1
    lp += cutoff * (noise.next() - lp);
    ph += 55 / kRate;
    b[i] = toSample((lp * 1.6f + 0.25f * sinf(kTau * ph)) * expf(-t * 3.5f));
  }
  return n;
}

// Siren: a sine wobbling between 550 and 1250 Hz a little faster than once a second.
inline uint32_t siren(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(2.2f * kRate));
  float ph = 0;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    ph += (900 + 350 * sinf(kTau * 1.2f * t)) / kRate;
    const float fade = std::min(1.0f, std::min(t, 2.2f - t) * 20);
    b[i] = toSample(sinf(kTau * ph) * 0.5f * fade);
  }
  return n;
}

// Modem: a dial tone (350 + 440 Hz), a burst of two-tone chirps (FSK: 1200 Hz = 1, 2200 Hz = 0),
// then a hiss: how computers talked over phone lines.
inline uint32_t modem(int16_t *b, uint32_t cap) {
  const uint32_t n = std::min<uint32_t>(cap, uint32_t(1.4f * kRate));
  Noise noise;
  float a = 0, c = 0;
  uint32_t bits = 0xB5E3;
  for (uint32_t i = 0; i < n; i++) {
    const float t = i / kRate;
    float v;
    if (t < 0.3f) {
      a += 350 / kRate, c += 440 / kRate;
      v = 0.25f * (sinf(kTau * a) + sinf(kTau * c));
    } else if (t < 0.9f) {
      const int bit = (bits >> (int((t - 0.3f) / 0.04f) % 16)) & 1;
      a += (bit ? 1200.0f : 2200.0f) / kRate;
      v = 0.4f * sinf(kTau * a);
    } else {
      v = 0.3f * noise.next() * expf(-(t - 0.9f) * 6);
    }
    b[i] = toSample(v);
  }
  return n;
}

inline const Fx *effects(int &count) {
  static const Fx kFx[] = {
      {"laser", "a square wave diving 2.4 kHz -> 150 Hz", laser},
      {"coin", "B5 then E6, square, ringing out", coin},
      {"jump", "a quick glide up, 250 -> 900 Hz", jump},
      {"powerup", "three rising arpeggios", powerUp},
      {"explosion", "noise through a closing low-pass filter", explosion},
      {"siren", "a sine wobbling 550-1250 Hz", siren},
      {"modem", "dial tone, two-tone chirps, hiss", modem},
  };
  count = sizeof(kFx) / sizeof(kFx[0]);
  return kFx;
}

}  // namespace s7

// The shell every sound lab (S1-S8) shares: the microphone and its sampler task, the speaker, the
// level meter, the screen with its header and footer, the push button and BOOT, the on-board RGB
// LED, and the serial commands every lab has (help, view, status, mic, vol, beep, tune, rate,
// atten, quiet, plot).
//
// Which microphone? `mic auto` (the default) listens for an INMP441 on the I2S pins at start-up and
// uses it when it answers, the KY-037 otherwise. `mic ky037` / `mic inmp441` force one (saved in
// NVS, then a restart). The speaker (MAX98357A) is always started: with nothing wired it is silent.
//
// Echo guard: while the speaker plays (and 200 ms after), the lab's frame() hook gets no frames, so
// a beep is never taken for a clap. A lab that wants to hear through it sets hearSpeaker.
//
// A lab is a SoundLabSpec: its views (each a draw function, plus what a double-click does there),
// its serial commands, and hooks: setup() once the mic runs, frame() for every 4 ms frame of sound
// (with the level already updated), tick() once per screen frame, gesture() for the button.
// Each src/sound-lab-sN/main.cpp is that list.
//
// Button or BOOT: click = next view · double-click = this view's action · long press = the lab's
// long action. On-board LED, unless the lab claims it: the level as a colour (green, amber, red),
// dim while quiet.
#pragma once

#include <Arduino.h>

#include "button.h"
#include "display.h"
#include <Preferences.h>

#include "level.h"
#include "mic.h"
#include "pins.h"
#include "sound_views.h"
#include "speaker.h"

class SoundLab;

enum class Gesture : uint8_t { Click, DoubleClick, LongPress };

struct SoundCommand {
  const char *name;  // the first word you type
  const char *args;  // for help, e.g. "<dB>"
  const char *what;  // one line for help
  void (*run)(SoundLab &lab, const String &arg, const String &lower);
};

struct SoundView {
  const char *name;  // "scope"
  void (*draw)(SoundLab &lab, FrameBuffer &fb, float t);
  const char *action;  // the command line a double-click runs on this view, or nullptr
};

struct SoundLabSpec {
  const char *env;    // "sound-lab-s1"
  const char *id;     // "S1"
  const char *title;  // "Hear"
  const SoundView *views;
  int viewCount;
  int startView;
  const SoundCommand *commands;
  int commandCount;
  void (*setup)(SoundLab &lab) = nullptr;
  void (*frame)(SoundLab &lab, const snd::Frame &f, uint32_t ms) = nullptr;  // every 4 ms of sound
  void (*tick)(SoundLab &lab) = nullptr;                                    // every screen frame
  bool (*gesture)(SoundLab &lab, Gesture g, bool external) = nullptr;       // true = handled
  const char *longAction = nullptr;
  bool hearSpeaker = false;  // true: frame() keeps running while the speaker plays (S8's effects)
};

// Little sounds every lab can make (only when a speaker is wired, of course).
enum class Chime : uint8_t { Click, Ok, No, Start, Stop, Score, Hello };

class SoundLab {
 public:
  explicit SoundLab(const SoundLabSpec &spec) : spec_(spec), view_(spec.startView) {}

  void begin() {
    Serial.begin(115200);
    delay(1500);
    if (!display_.begin()) {
      log_e("No memory for the frame buffer. Stopping.");
      return;
    }
    rgbLedWrite(PIN_RGB, 0, 0, 0);
    external_.begin();
    boot_.begin();
    Preferences prefs;
    prefs.begin("sound", true);
    const String choice = prefs.isKey("mic") ? prefs.getString("mic") : String("auto");
    const int volume = prefs.getInt("vol", 40);
    prefs.end();
    snd::Source source = snd::Source::Ky037;
    if (choice == "inmp441") source = snd::Source::Inmp441;
    else if (choice == "auto") {
      Serial.println("Listening for an INMP441 on the I2S pins...");
      if (snd::Mic::probeInmp441()) source = snd::Source::Inmp441;
    }
    Serial.printf("Microphone: %s (mic setting: %s)\n", snd::sourceName(source), choice.c_str());
    speakerOk_ = speaker_.begin();
    speaker_.setVolume(volume);
    if (!mic_.begin(source)) {
      log_e("The microphone sampler did not start. Stopping.");
      return;
    }
    if (spec_.setup) spec_.setup(*this);
    printHelp();
    chime(Chime::Hello);
    note(sv::Note::Info, "learning the quiet...");
  }

  void loop() {
    FrameBuffer &fb = display_.fb();
    if (fb.pixels() == nullptr) {
      delay(1000);
      return;
    }
    pollSerial();
    handleButton(external_, true);
    handleButton(boot_, false);
    takeFrames();
    if (spec_.tick) spec_.tick(*this);
    showLed();

    const float t = millis() / 1000.0f;
    const SoundView &v = spec_.views[view_];
    fb.fillScreen(pal::night);
    v.draw(*this, fb, t);
    sv::header(fb, spec_.id, v.name, view_, spec_.viewCount, level_.reading(), mic_.doHigh(), recording_, t, mic_.digital(),
               speaker_.busy());
    char hint[40];
    if (v.action) snprintf(hint, sizeof(hint), "2x: %s", v.action);
    else snprintf(hint, sizeof(hint), "click: next view");
    sv::footer(fb, hint, note_, noteKind_, millis() - noteAt_);
    display_.push();
  }

  // ---- For views and commands ------------------------------------------------------------------

  snd::Mic &mic() { return mic_; }
  snd::Speaker &speaker() { return speaker_; }
  // The level in dB SPL (INMP441 only; NAN with the KY-037, which has no known sensitivity).
  float spl() const { return mic_.splOf(level_.reading().fastDb); }
  const snd::LevelReading &level() const { return level_.reading(); }
  snd::Level &meter() { return level_; }
  Display &display() { return display_; }
  const SoundLabSpec &spec() const { return spec_; }
  int view() const { return view_; }
  // The sound clock: milliseconds of sound heard so far, advanced 64 samples' worth per frame. Every
  // detector runs on it (not millis()), so a slow screen frame never bends their timing.
  uint32_t soundMs() const { return uint32_t(soundMs_); }

  void setView(int v) {
    view_ = (v % spec_.viewCount + spec_.viewCount) % spec_.viewCount;
    log_i("view %d: %s", view_ + 1, spec_.views[view_].name);
  }
  void showView(const char *name) {
    for (int i = 0; i < spec_.viewCount; i++)
      if (strcmp(spec_.views[i].name, name) == 0) return setView(i);
  }

  // The lab drives the on-board LED itself; false hands it back to the level colour.
  void claimLed(bool claimed) {
    ledClaimed_ = claimed;
    ledShown_ = 0xFFFFFFFF;
  }
  // The REC dot in the header. The recorder sets it; nothing can record without it showing.
  void setRecording(bool on) { recording_ = on; }

  void chime(Chime c) {
    if (!speakerOk_) return;
    switch (c) {
      case Chime::Click: speaker_.tone(2400, 12, syn::Wave::Square, 0.4f); break;
      case Chime::Ok: speaker_.tune("E6/16 B6/8", 240, syn::Wave::Sine); break;
      case Chime::No: speaker_.tune("C4/16 r/32 C4/8", 200, syn::Wave::Square); break;
      case Chime::Start: speaker_.tune("G5/16 C6/16", 260, syn::Wave::Triangle); break;
      case Chime::Stop: speaker_.tune("C6/16 G5/16", 260, syn::Wave::Triangle); break;
      case Chime::Score: speaker_.tune("C6/32 E6/32 G6/32 C7/16", 240, syn::Wave::Square); break;
      case Chime::Hello: speaker_.tune("C5/16 E5/16 G5/8", 220, syn::Wave::Triangle); break;
    }
  }

  // A short line for the footer, also printed to serial.
  [[gnu::format(printf, 3, 4)]] void note(sv::Note kind, const char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(note_, sizeof(note_), fmt, ap);
    va_end(ap);
    noteKind_ = kind;
    noteAt_ = millis();
    Serial.printf("  %s %s\n", sv::noteMark(kind), note_);
  }

  // log_w is a macro that can't be returned from a void function; this can.
  [[gnu::format(printf, 2, 3)]] void warn(const char *fmt, ...) {
    char text[140];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(text, sizeof(text), fmt, ap);
    va_end(ap);
    log_w("%s", text);
  }

  static bool number(const String &arg, long lo, long hi, long &out) {
    if (arg.isEmpty()) return false;
    for (size_t i = 0; i < arg.length(); i++)
      if (!isDigit(arg[i]) && !(i == 0 && arg[i] == '-')) return false;
    out = arg.toInt();
    return out >= lo && out <= hi;
  }
  static bool decimal(const String &arg, float lo, float hi, float &out) {
    if (arg.isEmpty()) return false;
    char *end = nullptr;
    out = strtof(arg.c_str(), &end);
    return end && *end == 0 && out >= lo && out <= hi;
  }

  void runLine(const String &raw) {
    String line = raw;
    line.trim();
    if (line.isEmpty()) return;
    const int sp = line.indexOf(' ');
    String cmd = sp < 0 ? line : line.substring(0, sp);
    String arg = sp < 0 ? String() : line.substring(sp + 1);
    cmd.toLowerCase();
    arg.trim();
    String lower = arg;
    lower.toLowerCase();
    // The lab's own commands first, so a lab can give a shared word its own meaning.
    for (int i = 0; i < spec_.commandCount; i++)
      if (cmd == spec_.commands[i].name) return spec_.commands[i].run(*this, arg, lower);
    if (cmd == "help" || cmd == "?") return printHelp();
    if (cmd == "view") {
      long n = 0;
      if (!number(arg, 1, spec_.viewCount, n)) return warn("view <1-%d>", spec_.viewCount);
      return setView(n - 1);
    }
    if (cmd == "status") return printStatus();
    if (cmd == "mic") return cmdMic(lower);
    if (cmd == "vol") return cmdVol(arg);
    if (cmd == "beep") return cmdBeep(arg, lower);
    if (cmd == "tune") return cmdTune(lower);
    if (cmd == "rate") return cmdRate(arg);
    if (cmd == "atten") return cmdAtten(lower);
    if (cmd == "quiet") {
      level_.relearn();
      return note(sv::Note::Info, "shh... learning the quiet");
    }
    if (cmd == "plot") {
      plot_ = lower != "off";
      return note(sv::Note::Info, plot_ ? "plot on: one bar per 50 ms" : "plot off");
    }
    log_w("unknown command '%s' in %s (type help)", line.c_str(), spec_.env);
  }

 private:
  void printHelp() {
    Serial.printf("\nSound lab %s %s  (%s)  ·  microphone: %s\n", spec_.id, spec_.title, spec_.env, snd::sourceName(mic_.source()));
    for (int i = 0; i < spec_.commandCount; i++) {
      const SoundCommand &c = spec_.commands[i];
      char usage[40];
      snprintf(usage, sizeof(usage), "%s %s", c.name, c.args);
      Serial.printf("  %-28s %s\n", usage, c.what);
    }
    Serial.printf("  %-28s %s\n", "quiet", "re-learn the quiet of your room (half a second: shh)");
    Serial.printf("  %-28s %s\n", "plot [off]", "print the level as a bar every 50 ms");
    Serial.printf("  %-28s %s\n", "status", "the sampler, the microphone and the level, in numbers");
    Serial.printf("  %-28s %s\n", "mic [auto|ky037|inmp441]", "which microphone (saved; restarts)");
    Serial.printf("  %-28s %s\n", "vol <0-100>", "speaker volume (saved, default 40)");
    Serial.printf("  %-28s %s\n", "beep [Hz] [wave]", "a test tone on the speaker (sine square triangle saw noise)");
    Serial.printf("  %-28s %s\n", "tune <name>", "play a tune: hello scale twinkle ode alarm");
    Serial.printf("  %-28s %s\n", "rate <Hz>", "sample rate, 2000-48000 (default 16000)");
    Serial.printf("  %-28s %s\n", "atten <0|2.5|6|12>", "the ADC's input range (default 12 dB = 0-3.1 V)");
    Serial.printf("  %-28s %s\n", "view <n>", "show screen view n");
    Serial.print("Views:");
    for (int i = 0; i < spec_.viewCount; i++)
      Serial.printf(" %d %s%s", i + 1, spec_.views[i].name, i + 1 < spec_.viewCount ? " ·" : "\n");
    Serial.println("Button (GPIO 5, optional) or BOOT: click = next view, double-click = the view's action");
  }

  void printStatus() {
    const snd::LevelReading &r = level_.reading();
    Serial.printf("sampler: %lu Hz asked, %lu Hz measured · frames dropped %lu · DMA overruns %lu\n",
                  static_cast<unsigned long>(mic_.rate()), static_cast<unsigned long>(mic_.measuredRate()),
                  static_cast<unsigned long>(mic_.framesDropped()), static_cast<unsigned long>(mic_.overruns()));
    if (mic_.digital())
      Serial.printf("INMP441: 24-bit, offset %d · last 100 ms %d..%d of +-%d%s · dB SPL = dBFS + %.0f\n", int(mic_.biasRaw()), mic_.rawLow(),
                    mic_.rawHigh(), mic_.rawMax(), mic_.clipping() ? " CLIPPING" : "", snd::Mic::kInmp441Spl);
    else
      Serial.printf("KY-037 on the ADC: attenuation %s · bias %d mV (raw %d) · last 100 ms raw %d..%d%s · %s\n", snd::attenName(mic_.atten()),
                    mic_.biasMv(), int(mic_.biasRaw()), mic_.rawLow(), mic_.rawHigh(), mic_.clipping() ? " CLIPPING" : "",
                    mic_.calibrated() ? "eFuse calibration" : "no calibration (straight-line mV)");
    Serial.printf("level: %.1f dBFS fast, %.1f slow, floor %.1f dBFS · %.1f dB above the quiet · peak %.1f dBFS\n", r.fastDb, r.slowDb,
                  r.floorDb, r.above(), r.peakDb);
    if (mic_.digital()) Serial.printf("sound level: about %.0f dB SPL (unweighted)\n", spl());
    else Serial.printf("comparator DO: %s now, %lu rising edges\n", mic_.doHigh() ? "HIGH" : "low", static_cast<unsigned long>(mic_.doRises()));
    Serial.printf("speaker: volume %d, %s\n", speaker_.volume(), speaker_.busy() ? "playing" : "quiet");
  }

  void cmdRate(const String &arg) {
    long hz = 0;
    if (!number(arg, 2000, 48000, hz)) return warn("rate <Hz>, 2000-48000. Now %lu", static_cast<unsigned long>(mic_.rate()));
    mic_.reconfigure(uint32_t(hz), mic_.atten());
    level_ = snd::Level(snd::kChunk * 1000.0f / float(hz));  // a frame is 64 samples: its length changes
    note(sv::Note::Info, "rate %ld Hz", hz);
  }

  void cmdMic(const String &lower) {
    if (lower != "auto" && lower != "ky037" && lower != "inmp441")
      return warn("mic auto | mic ky037 | mic inmp441   (now: %s)", snd::sourceName(mic_.source()));
    Preferences prefs;
    prefs.begin("sound", false);
    prefs.putString("mic", lower);
    prefs.end();
    Serial.printf("mic %s saved. Restarting to switch...\n", lower.c_str());
    Serial.flush();
    delay(200);
    ESP.restart();
  }

  void cmdVol(const String &arg) {
    long v = 0;
    if (!number(arg, 0, 100, v)) return warn("vol <0-100>   (now %d)", speaker_.volume());
    speaker_.setVolume(int(v));
    Preferences prefs;
    prefs.begin("sound", false);
    prefs.putInt("vol", int(v));
    prefs.end();
    chime(Chime::Click);
    note(sv::Note::Info, "volume %ld", v);
  }

  void cmdBeep(const String &arg, const String &lower) {
    float hz = 880;
    syn::Wave wave = syn::Wave::Sine;
    const int sp = lower.indexOf(' ');
    if (!arg.isEmpty() && !decimal(sp < 0 ? arg : arg.substring(0, sp), 20, 8000, hz)) return warn("beep [Hz 20-8000] [sine|square|triangle|saw|noise]");
    if (sp > 0 && !syn::parseWave(lower.substring(sp + 1).c_str(), wave)) return warn("wave: sine square triangle saw noise");
    speaker_.tone(hz, 400, wave);
    note(sv::Note::Info, "beep %.0f Hz %s", hz, syn::waveName(wave));
  }

  void cmdTune(const String &lower) {
    static const struct {
      const char *name, *notes;
      int bpm;
    } kTunes[] = {
        {"hello", "C5/16 E5/16 G5/8", 220},
        {"scale", "C4/8 D4/8 E4/8 F4/8 G4/8 A4/8 B4/8 C5/4", 160},
        {"twinkle", "C5/4 C5/4 G5/4 G5/4 A5/4 A5/4 G5/2 F5/4 F5/4 E5/4 E5/4 D5/4 D5/4 C5/2", 160},
        {"ode", "E5/4 E5/4 F5/4 G5/4 G5/4 F5/4 E5/4 D5/4 C5/4 C5/4 D5/4 E5/4 E5/4. D5/8 D5/2", 150},
        {"alarm", "A5/16 E5/16 A5/16 E5/16 A5/16 E5/16 A5/16 E5/16", 200},
    };
    for (const auto &t : kTunes)
      if (lower == t.name) {
        speaker_.tune(t.notes, t.bpm);
        return note(sv::Note::Info, "playing %s", t.name);
      }
    warn("tune hello | scale | twinkle | ode | alarm");
  }

  void cmdAtten(const String &lower) {
    if (mic_.digital()) return warn("atten is for the KY-037's ADC: the INMP441 has its own converter inside");
    adc_atten_t a;
    if (lower == "0") a = ADC_ATTEN_DB_0;
    else if (lower == "2.5") a = ADC_ATTEN_DB_2_5;
    else if (lower == "6") a = ADC_ATTEN_DB_6;
    else if (lower == "12" || lower == "11") a = ADC_ATTEN_DB_12;
    else return warn("atten 0 | 2.5 | 6 | 12   (now %s)", snd::attenName(mic_.atten()));
    mic_.reconfigure(mic_.rate(), a);
    level_.relearn();
    note(sv::Note::Info, "attenuation %s", snd::attenName(a));
  }

  // All frames the sampler has queued since the last screen frame: level first, then the lab.
  void takeFrames() {
    snd::Frame f;
    while (mic_.frame(f)) {
      soundMs_ += snd::kChunk * 1000.0 / mic_.rate();
      const uint32_t ms = uint32_t(soundMs_);
      level_.push(f.rms, ms);
      // The echo guard: the board's own sounds are not claps, knocks or voices.
      if (spec_.frame && (spec_.hearSpeaker || !speaker_.recentlyLoud(200))) spec_.frame(*this, f, ms);
      if (plot_ && ms - plotAt_ >= 50) plotAt_ = ms, printPlot();
    }
  }

  void printPlot() {
    const snd::LevelReading &r = level_.reading();
    char bar[41];
    const int n = int(snd::meterFraction(r.instAbove(), 60) * 40);
    for (int i = 0; i < 40; i++) bar[i] = i < n ? '#' : (i == int(snd::meterFraction(r.peakDb - r.floorDb, 60) * 40) ? '|' : ' ');
    bar[40] = 0;
    if (mic_.digital()) Serial.printf("%5.1f dB |%s| %3.0f dB SPL\n", r.instAbove(), bar, mic_.splOf(r.instDb));
    else Serial.printf("%5.1f dB |%s| DO %c\n", r.instAbove(), bar, mic_.doHigh() ? '1' : '0');
  }

  void pollSerial() {
    static String buffer;
    while (Serial.available()) {
      const char c = Serial.read();
      if (c == '\n' || c == '\r') {
        if (!buffer.isEmpty()) runLine(buffer);
        buffer = "";
      } else if (c == 0x08 || c == 0x7F) {
        if (!buffer.isEmpty()) buffer.remove(buffer.length() - 1);
      } else if (uint8_t(c) >= 0x20 && buffer.length() < 120) {
        buffer += c;
      }
    }
  }

  void handleButton(Button &b, bool external) {
    Gesture g;
    switch (b.poll()) {
      case Button::Event::Click: g = Gesture::Click; break;
      case Button::Event::DoubleClick: g = Gesture::DoubleClick; break;
      case Button::Event::LongPress: g = Gesture::LongPress; break;
      default: return;
    }
    if (spec_.gesture && spec_.gesture(*this, g, external)) return;
    switch (g) {
      case Gesture::Click: setView(view_ + 1); break;
      case Gesture::DoubleClick:
        if (spec_.views[view_].action) {
          Serial.printf("> %s   (double-click)\n", spec_.views[view_].action);
          runLine(spec_.views[view_].action);
        }
        break;
      case Gesture::LongPress:
        if (spec_.longAction) {
          Serial.printf("> %s   (long press)\n", spec_.longAction);
          runLine(spec_.longAction);
        }
        break;
    }
  }

  void showLed() {
    if (ledClaimed_) return;
    uint8_t r = 0, g = 0, b = 0;
    if (recording_) r = 90;  // the recorder always shows itself, here too
    else {
      // 8 brightness steps, so the LED (a whole WS2812 frame per write) only changes when it should.
      const float above = level_.reading().above();
      const uint8_t v = uint8_t(4 + int(snd::meterFraction(above, 50) * 7) * 12);
      if (above < 25) g = v;
      else if (above < 40) r = v, g = v / 2;
      else r = v;
    }
    const uint32_t colour = (uint32_t(r) << 16) | (uint32_t(g) << 8) | b;
    if (colour == ledShown_) return;
    ledShown_ = colour;
    rgbLedWrite(PIN_RGB, r, g, b);
  }

  const SoundLabSpec &spec_;
  Display display_;
  Button external_{PIN_BUTTON, "button"};
  Button boot_{PIN_BOOT_BTN, "BOOT"};
  snd::Mic mic_;
  snd::Speaker speaker_;
  snd::Level level_;
  bool speakerOk_ = false;
  int view_;
  bool ledClaimed_ = false, recording_ = false, plot_ = false;
  uint32_t ledShown_ = 0xFFFFFFFF, plotAt_ = 0;
  double soundMs_ = 0;
  char note_[64] = "";
  sv::Note noteKind_ = sv::Note::Info;
  uint32_t noteAt_ = 0;
};

// Which frequencies are in the sound? Our own FFT (fast Fourier transform), no library.
//
// A sound is many waves at once. The FFT takes N samples (say 512 = 32 ms at 16 kHz) and
// answers, for each of N/2 "bins", how strong the wave at that frequency is. Bin k is
// k x rate / N Hz wide steps: 16000 / 512 = 31.25 Hz apart. More samples = finer bins, but a
// slower answer (you wait N samples for each one).
//
// The window: the FFT pretends the N samples repeat forever. Where the end doesn't meet the
// start, that jump smears energy into every bin ("leakage"). Multiplying by a Hann window (a hump
// that is 0 at both ends) removes the jump.
//
// Radix-2: split the samples into even and odd, solve each half, combine with "butterflies".
// log2(N) passes of N/2 butterflies: 512 points = 9 x 256 = 2304 butterflies, ~0.2 ms on the S3.
//
// Pure C++: host-tested in kit/test/host/sound_dsp_test.cpp.
#pragma once

#include <math.h>
#include <stdint.h>
#include <stdio.h>

#include <algorithm>

namespace snd {

class Fft {
 public:
  static constexpr int kMaxN = 1024;

  // n must be a power of two, 64-1024.
  bool setSize(int n) {
    if (n < 64 || n > kMaxN || (n & (n - 1))) return false;
    n_ = n;
    bits_ = 0;
    while ((1 << bits_) < n) bits_++;
    for (int i = 0; i < n / 2; i++) {
      cos_[i] = cosf(2.0f * float(M_PI) * i / n);
      sin_[i] = -sinf(2.0f * float(M_PI) * i / n);
    }
    for (int i = 0; i < n; i++) window_[i] = 0.5f - 0.5f * cosf(2.0f * float(M_PI) * i / (n - 1));
    return true;
  }

  int size() const { return n_; }
  int bins() const { return n_ / 2; }

  // Window + transform n int16 samples. Then magnitude(k) / db(k) for k < bins().
  void run(const int16_t *samples) {
    for (int i = 0; i < n_; i++) re_[reverse(i)] = samples[i] * window_[i], im_[reverse(i)] = 0;
    for (int half = 1, step = n_ / 2; half < n_; half *= 2, step /= 2)
      for (int start = 0; start < n_; start += 2 * half)
        for (int k = 0; k < half; k++) {
          const int a = start + k, b = a + half;
          const float c = cos_[k * step], s = sin_[k * step];
          const float tr = re_[b] * c - im_[b] * s, ti = re_[b] * s + im_[b] * c;
          re_[b] = re_[a] - tr, im_[b] = im_[a] - ti;
          re_[a] += tr, im_[a] += ti;
        }
    // Scale so a full-scale sine reads about 0 dB: 2 / N for one side, x2 for the Hann window's loss.
    const float scale = 4.0f / (n_ * 32768.0f);
    for (int k = 0; k < n_ / 2; k++) mag_[k] = sqrtf(re_[k] * re_[k] + im_[k] * im_[k]) * scale;
  }

  float magnitude(int k) const { return mag_[k]; }
  float db(int k) const { return mag_[k] < 1e-6f ? -120.0f : 20.0f * log10f(mag_[k]); }
  float binHz(int k, float rate) const { return k * rate / n_; }

  // The strongest bin between lo and hi Hz, refined between bins with a parabola through its
  // neighbours. clarity = how far it stands above the average in that range (dB).
  struct Peak {
    float hz = 0;
    float db = -120;
    float clarity = 0;
  };
  Peak peak(float rate, float loHz, float hiHz) const {
    const int lo = std::max(1, int(loHz * n_ / rate)), hi = std::min(n_ / 2 - 2, int(hiHz * n_ / rate));
    Peak p;
    if (hi <= lo) return p;
    int best = lo;
    float sum = 0;
    for (int k = lo; k <= hi; k++) {
      sum += mag_[k];
      if (mag_[k] > mag_[best]) best = k;
    }
    const float a = mag_[best - 1], b = mag_[best], c = mag_[best + 1];
    const float den = a - 2 * b + c;
    const float shift = den != 0 ? 0.5f * (a - c) / den : 0;
    p.hz = (best + shift) * rate / n_;
    p.db = db(best);
    const float avg = sum / (hi - lo + 1);
    p.clarity = avg > 1e-9f ? 20.0f * log10f(b / avg) : 0;
    return p;
  }

  // Bands spaced evenly in octaves (how we hear) from loHz to hiHz: the strongest bin in each, dB.
  void bands(float rate, float loHz, float hiHz, float *outDb, int count) const {
    for (int i = 0; i < count; i++) {
      const float f0 = loHz * powf(hiHz / loHz, float(i) / count), f1 = loHz * powf(hiHz / loHz, float(i + 1) / count);
      int k0 = std::max(1, int(f0 * n_ / rate)), k1 = std::min(n_ / 2 - 1, int(f1 * n_ / rate));
      if (k1 < k0) k1 = k0;
      float m = 0;
      for (int k = k0; k <= k1; k++) m = std::max(m, mag_[k]);
      outDb[i] = m < 1e-6f ? -120.0f : 20.0f * log10f(m);
    }
  }

 private:
  int reverse(int i) const {
    int r = 0;
    for (int b = 0; b < bits_; b++) r |= ((i >> b) & 1) << (bits_ - 1 - b);
    return r;
  }

  int n_ = 0, bits_ = 0;
  float re_[kMaxN], im_[kMaxN], window_[kMaxN], mag_[kMaxN / 2];
  float cos_[kMaxN / 2], sin_[kMaxN / 2];
};

// Musical notes: A4 = 440 Hz by default, every semitone x 2^(1/12). midi 69 = A4.
struct Note {
  int midi = 0;
  float cents = 0;  // -50..+50: how far off the nearest note (100 cents = one semitone)
  char name[8] = "";  // "A4", "C#5"
};

// a4 = the tuning reference (440 Hz is the standard; some orchestras tune to 442).
inline Note noteOf(float hz, float a4 = 440.0f) {
  Note n;
  if (hz <= 0) return n;
  const float m = 69.0f + 12.0f * log2f(hz / a4);
  n.midi = int(lroundf(m));
  n.cents = (m - n.midi) * 100.0f;
  static const char *const kNames[] = {"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"};
  snprintf(n.name, sizeof(n.name), "%s%d", kNames[((n.midi % 12) + 12) % 12], n.midi / 12 - 1);
  return n;
}

}  // namespace snd

// A push button on any GPIO, wired between the pin and GND.
//
// Wiring: we turn on the chip's internal pull-up resistor, so the pin reads HIGH when the
// button is up and LOW when pressed (the button connects it to GND). No resistor needed.
//
// Bounce: the metal contacts inside a button flicker on/off for a few milliseconds on
// every press and release. Our screen loop only looks about 22 times a second, far too
// slowly to see that. So an interrupt counts every single edge the instant it happens,
// and poll() only trusts a new state once the pin has been quiet for kDebounceMs.
//
// Gestures, reported by poll():
//   Click        press and release, then nothing else for kDoubleGapMs
//   DoubleClick  two clicks within kDoubleGapMs
//   LongPress    held for kLongPressMs (fires while still held, so it feels instant)
#pragma once

#include <Arduino.h>
#include <esp_timer.h>

class Button {
 public:
  enum class Event { None, Click, DoubleClick, LongPress };

  Button(uint8_t pin, const char *name) : pin_(pin), name_(name) {}

  void begin() {
    pinMode(pin_, INPUT_PULLUP);
    // CHANGE = run onEdge on every rising and falling edge, bounces included.
    attachInterruptArg(digitalPinToInterrupt(pin_), onEdge, this, CHANGE);
  }

  const char *name() const { return name_; }
  bool isDown() const { return pressed_; }
  // Raw edges seen during the last press + release, minus the 2 a perfect button makes.
  uint32_t lastBounces() const { return lastBounces_; }

  Event poll() {
    const uint32_t nowUs = uint32_t(esp_timer_get_time());
    const uint32_t now = millis();

    // 1. Debounce: accept the pin's level once no edge has arrived for kDebounceMs.
    const bool level = digitalRead(pin_) == LOW;
    if (level != pressed_ && nowUs - lastEdgeUs_ >= kDebounceMs * 1000) {
      pressed_ = level;
      if (pressed_) {
        pressedAt_ = now;
        longFired_ = false;
      } else {
        // Every edge since the previous release belongs to this press + release.
        const uint32_t edges = edges_ - edgesAtRest_;
        edgesAtRest_ = edges_;
        lastBounces_ = edges > 2 ? edges - 2 : 0;
        if (!longFired_) {
          clicks_++;
          releasedAt_ = now;
        }
      }
    }

    // 2. Turn clean presses into gestures.
    if (pressed_ && !longFired_ && now - pressedAt_ >= kLongPressMs) {
      longFired_ = true;
      clicks_ = 0;
      return Event::LongPress;
    }
    if (!pressed_ && clicks_ >= 2) {
      clicks_ = 0;
      return Event::DoubleClick;
    }
    if (!pressed_ && clicks_ == 1 && now - releasedAt_ >= kDoubleGapMs) {
      clicks_ = 0;
      return Event::Click;
    }
    return Event::None;
  }

 private:
  static constexpr uint32_t kDebounceMs = 25;
  static constexpr uint32_t kLongPressMs = 600;
  static constexpr uint32_t kDoubleGapMs = 280;

  // Runs inside the interrupt: keep it tiny. IRAM_ATTR keeps it in fast internal RAM.
  static void IRAM_ATTR onEdge(void *arg) {
    auto *self = static_cast<Button *>(arg);
    self->edges_ = self->edges_ + 1;
    self->lastEdgeUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  uint8_t pin_;
  const char *name_;
  volatile uint32_t edges_ = 0;      // written by the interrupt
  volatile uint32_t lastEdgeUs_ = 0;  // written by the interrupt
  bool pressed_ = false;
  bool longFired_ = false;
  uint8_t clicks_ = 0;
  uint32_t edgesAtRest_ = 0;
  uint32_t lastBounces_ = 0;
  uint32_t pressedAt_ = 0;
  uint32_t releasedAt_ = 0;
};

// The 1.9" ST7789 screen plus an off-screen frame buffer, set up the way every lesson since 03 uses it.
// Draw into fb() with the normal Adafruit GFX calls, then push() sends the whole picture at once.
#pragma once

#include <Adafruit_ST7789.h>
#include <SPI.h>

#include "frame_buffer.h"
#include "pins.h"

class Display {
 public:
  static constexpr int16_t kW = 320, kH = 170;  // landscape

  Display() : tft_(&SPI, PIN_TFT_CS, PIN_TFT_DC, PIN_TFT_RST), fb_(kW, kH) {}

  // Returns false if there is no memory for the frame buffer.
  bool begin(uint32_t spiHz = 40'000'000) {
    // Backlight through PWM so it can be dimmed (setBacklight). Full brightness to start.
    ledcAttach(PIN_TFT_BL, 5000, 8);
    ledcWrite(PIN_TFT_BL, 255);
    SPI.begin(PIN_TFT_SCLK, -1, PIN_TFT_MOSI, PIN_TFT_CS);
    tft_.init(170, 320);
    tft_.setSPISpeed(spiHz);
    tft_.setRotation(1);
    tft_.fillScreen(0);
    return fb_.begin();
  }

  FrameBuffer &fb() { return fb_; }
  // 0 = off, 255 = full brightness.
  void setBacklight(uint8_t level) { ledcWrite(PIN_TFT_BL, level); }
  void push() { tft_.drawRGBBitmap(0, 0, fb_.pixels(), kW, kH); }

 private:
  Adafruit_ST7789 tft_;
  FrameBuffer fb_;
};

// How loud is it? Decibels from the microphone's samples, the way a sound level meter shows them.
//
// The sampler (mic.h) cuts the sound into frames of 64 samples (4 ms at 16 kHz) and hands each
// frame's RMS (root mean square: the "average strength" of a wave that swings + and -) and peak.
//
// Decibels: our ears hear ratios, not differences. dB = 20 x log10(level / reference), so every
// +6 dB doubles the wave's height and +20 dB is ten times. Two scales here:
//   dBFS     relative to the ADC's full scale (0 dBFS = the loudest the ADC can show). Always <= 0.
//   above    dB above the quietest your room gets (the noise floor). 0 = silence, 20 = talking
//            close by, 40+ = a clap at arm's length. This is the number the labs mostly use.
// Neither is "dB SPL" (what a calibrated meter shows): that would need a reference microphone.
//
// Fast and slow: real meters smooth the level with a 125 ms ("fast") or 1 s ("slow") time
// constant. We smooth the power (RMS squared) the same way, then convert to dB.
//
// The noise floor follows the quiet: it drops at once to anything quieter and creeps up by
// 0.5 dB a second, so a minute of steady noise (a fan) becomes the new "quiet". `quiet` re-learns it.
//
// Pure C++ (no Arduino): host-tested in kit/test/host/sound_dsp_test.cpp.
#pragma once

#include <math.h>
#include <stdint.h>

namespace snd {

constexpr float kFloorDb = -96.0f;  // what silence (an RMS below 1 of 32768) reads as

inline float toDb(float rms) { return rms < 0.5f ? kFloorDb : 20.0f * log10f(rms / 32768.0f); }
inline float powerToDb(float power) { return power < 0.25f ? kFloorDb : 10.0f * log10f(power / (32768.0f * 32768.0f)); }

// Smoothing factor for a time constant, for frames of frameMs.
inline float alphaFor(float tauMs, float frameMs) { return 1.0f - expf(-frameMs / tauMs); }

struct LevelReading {
  float instDb = kFloorDb;  // this frame alone (4 ms): claps and knocks live here
  float fastDb = kFloorDb;  // 125 ms
  float slowDb = kFloorDb;  // 1 s
  float peakDb = kFloorDb;  // the highest instDb lately, held 1.5 s then falling 20 dB/s
  float floorDb = 0;         // the noise floor
  float above() const { return fastDb > floorDb ? fastDb - floorDb : 0.0f; }
  float instAbove() const { return instDb > floorDb ? instDb - floorDb : 0.0f; }
  float slowAbove() const { return slowDb > floorDb ? slowDb - floorDb : 0.0f; }
};

class Level {
 public:
  explicit Level(float frameMs = 4.0f)
      : frameMs_(frameMs), aFast_(alphaFor(125, frameMs)), aSlow_(alphaFor(1000, frameMs)), floorRise_(0.5f * frameMs / 1000.0f) {}

  // One frame: its RMS (in int16 units) and the time it ended (ms).
  void push(float rms, uint32_t ms) {
    const float power = rms * rms;
    if (frames_ == 0) fastP_ = slowP_ = power;
    fastP_ += aFast_ * (power - fastP_);
    slowP_ += aSlow_ * (power - slowP_);
    r_.instDb = toDb(rms);
    r_.fastDb = powerToDb(fastP_);
    r_.slowDb = powerToDb(slowP_);

    // Peak hold: jump up at once, hold 1.5 s, then fall 20 dB a second.
    if (r_.instDb >= r_.peakDb) r_.peakDb = r_.instDb, peakAt_ = ms;
    else if (ms - peakAt_ > 1500) r_.peakDb -= 20.0f * frameMs_ / 1000.0f;

    // Noise floor: the average power of the first half second, then it follows the quiet.
    if (learned_ < learnFrames()) learnP_ += power, r_.floorDb = powerToDb(learnP_ / float(++learned_));
    else if (r_.fastDb < r_.floorDb) r_.floorDb = r_.fastDb;
    else r_.floorDb += floorRise_;
    frames_++;
  }

  // Forget the floor: the next half second becomes the new quiet.
  void relearn() {
    learned_ = 0;
    learnP_ = 0;
  }
  bool learning() const { return learned_ < learnFrames(); }

  const LevelReading &reading() const { return r_; }

 private:
  uint32_t learnFrames() const { return uint32_t(500 / frameMs_); }

  float frameMs_, aFast_, aSlow_, floorRise_;
  float fastP_ = 0, slowP_ = 0, learnP_ = 0;
  uint32_t frames_ = 0, learned_ = 0, peakAt_ = 0;
  LevelReading r_;
};

// A 0-1 position for a meter that shows `rangeDb` dB above the floor.
inline float meterFraction(float aboveDb, float rangeDb = 60.0f) {
  const float f = aboveDb / rangeDb;
  return f < 0 ? 0 : f > 1 ? 1 : f;
}

}  // namespace snd

// The microphone, whichever one is wired: sampled 16 000 times a second, the same pipeline after.
//
// Two sources, one class:
//   KY-037   analog. Its AO pin is a small wave on top of a steady voltage (the "bias"). The ESP32's
//            own ADC measures it, 12 bits (0-4095). No amplifier: a good loudness sensor, hissy for
//            voices. Its DO pin is the comparator's yes/no, watched by an interrupt.
//   INMP441  digital. The microphone has its own amplifier and a 24-bit ADC inside, and sends
//            numbers over I2S (a clock, a left/right line, a data line). No bias, no ADC noise, and
//            its sensitivity is in the datasheet (-26 dBFS at 94 dB SPL), so S2 can show real dB SPL.
//
// Why not analogRead() in loop()? It takes one sample when asked, and loop() also draws the screen
// (~40 ms a frame), so we would get a few samples a frame, unevenly spaced: useless for sound.
// Both sources run on their own clock instead: the ADC in "continuous" mode, the I2S peripheral as
// the microphone's clock master, each with DMA (direct memory access) moving results into RAM with
// no CPU involved. A sampler task on core 0 (the screen loop runs on core 1) picks them up and:
//
//   1. removes the DC part: a very slow average follows it, and every sample becomes "raw - average",
//      a wave around 0 (the KY-037's bias, or the INMP441's small offset).
//   2. scales it to 16 bits and stores it in a 4-second ring in PSRAM. Each sample has a running
//      number (`written()`): the scope, FFT and recorder copy stretches out of the ring by number,
//      whenever they like, without stopping the sampler.
//   3. every 64 samples (4 ms) measures the chunk's RMS and peak and queues it as a Frame. The lab
//      shell turns frames into the level meter and the clap, knock and beat detectors.
//
// Pins (kit/include/pins.h): KY-037 AO must be an ADC1 pin (ADC2 is busy while Wi-Fi is on). The
// INMP441 uses the I2S0 peripheral; the speaker (speaker.h) uses I2S1, so both can run at once.
#pragma once

#include <Arduino.h>
#include <driver/gpio.h>
#include <driver/i2s_std.h>
#include <esp_adc/adc_cali.h>
#include <esp_adc/adc_cali_scheme.h>
#include <esp_adc/adc_continuous.h>
#include <esp_heap_caps.h>
#include <esp_timer.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

#include <atomic>

#include "pins.h"

namespace snd {

constexpr int kChunk = 64;  // samples per frame

enum class Source : uint8_t { Ky037, Inmp441 };
inline const char *sourceName(Source s) { return s == Source::Inmp441 ? "INMP441 (I2S, digital)" : "KY-037 (ADC, analog)"; }
inline const char *sourceShort(Source s) { return s == Source::Inmp441 ? "INMP441" : "KY-037"; }

struct Frame {
  uint32_t end;   // the sample number just after this frame
  float rms;      // int16 units
  int16_t peak;   // the biggest |sample|
};

// Attenuation (KY-037 only): how much the ADC divides the input before measuring. More = a wider
// voltage range, fewer millivolts per step. The S3's usable ranges, roughly: 0 dB to ~0.95 V,
// 2.5 dB ~1.25 V, 6 dB ~1.75 V, 12 dB ~3.1 V. The bias must sit inside the range, with room for the wave.
inline const char *attenName(adc_atten_t a) {
  switch (a) {
    case ADC_ATTEN_DB_0: return "0 dB (0-0.95 V)";
    case ADC_ATTEN_DB_2_5: return "2.5 dB (0-1.25 V)";
    case ADC_ATTEN_DB_6: return "6 dB (0-1.75 V)";
    default: return "12 dB (0-3.1 V)";
  }
}
inline int attenTopMv(adc_atten_t a) { return a == ADC_ATTEN_DB_0 ? 950 : a == ADC_ATTEN_DB_2_5 ? 1250 : a == ADC_ATTEN_DB_6 ? 1750 : 3100; }

class Mic {
 public:
  static constexpr uint32_t kRing = 1 << 16;  // samples: 4.1 s at 16 kHz, 128 KB of PSRAM
  static constexpr uint32_t kMask = kRing - 1;
  // INMP441: its 24-bit sample >> 6 = our int16. That's 12 dB of gain over plain 16 bits: a quiet
  // room still uses a few bits, and it clips only around 114 dB SPL (a clap right at the mic).
  static constexpr int kI2sShift = 8 + 6;
  // dB SPL = our RMS dBFS + this (INMP441 only): -26 dBFS at 94 dB SPL, +12 dB for the shift above,
  // +3 dB because a full-scale sine has an RMS 3 dB under its peak. About +-2 dB, no A-weighting.
  static constexpr float kInmp441Spl = 94.0f + 26.0f - 12.0f + 3.0f;

  // Is an INMP441 answering on the I2S pins? With the data line pulled down, a missing microphone
  // reads as zeros; a real one never sends 100 ms of perfect silence. Takes ~0.3 s.
  static bool probeInmp441() {
    i2s_chan_handle_t rx = nullptr;
    if (!startI2s(rx, 16000)) return false;
    static int32_t buf[512];
    bool alive = false;
    const uint32_t until = millis() + 350;
    while (millis() < until) {
      size_t got = 0;
      if (i2s_channel_read(rx, buf, sizeof(buf), &got, 50) != ESP_OK) continue;
      if (millis() + 150 > until)  // the INMP441 needs ~85 ms to wake up: judge only the end
        for (size_t i = 0; i < got / 4; i++) alive |= buf[i] != 0 && buf[i] != -1;
    }
    i2s_channel_disable(rx);
    i2s_del_channel(rx);
    return alive;
  }

  bool begin(Source source, uint32_t rate = 16000, adc_atten_t atten = ADC_ATTEN_DB_12) {
    ring_ = static_cast<int16_t *>(heap_caps_calloc(kRing, sizeof(int16_t), MALLOC_CAP_SPIRAM));
    frames_ = xQueueCreate(256, sizeof(Frame));  // ~1 s of frames: loop() can be slow for a while
    if (!ring_ || !frames_) {
      log_e("Mic: no memory for the sample ring");
      return false;
    }
    source_ = source;
    rate_ = wantRate_ = rate;
    atten_ = wantAtten_ = atten;
    if (!startSource()) return false;
    if (source_ == Source::Ky037) {
      pinMode(PIN_MIC_DO, INPUT);  // the module drives DO itself (its own pull-up resistor)
      attachInterruptArg(digitalPinToInterrupt(PIN_MIC_DO), onDoEdge, this, RISING);
    }
    xTaskCreatePinnedToCore(task, "mic", 4096, this, 5, &task_, 0);
    return true;
  }

  // Change the sample rate and/or attenuation (KY-037). The task restarts the source between reads.
  void reconfigure(uint32_t rate, adc_atten_t atten) {
    wantRate_ = rate;
    wantAtten_ = atten;
    reconfigure_ = true;
  }

  Source source() const { return source_; }
  bool digital() const { return source_ == Source::Inmp441; }
  uint32_t rate() const { return rate_; }
  adc_atten_t atten() const { return atten_; }
  // dB SPL for a dBFS level, or NAN when the microphone has no known sensitivity (KY-037).
  float splOf(float dbfs) const { return digital() ? dbfs + kInmp441Spl : NAN; }

  // ---- The sound -------------------------------------------------------------------------------

  // Running sample number: how many samples have ever been stored.
  uint32_t written() const { return written_.load(std::memory_order_acquire); }

  // Copy n samples starting at sample number `from`. False if they're no longer (or not yet) in the ring.
  bool copy(uint32_t from, int16_t *out, uint32_t n) const {
    const uint32_t w = written();
    if (from + n > w || w - from > kRing - 1024) return false;  // 1024 = margin for the writer
    for (uint32_t i = 0; i < n; i++) out[i] = ring_[(from + i) & kMask];
    return true;
  }
  // The newest n samples.
  bool latest(int16_t *out, uint32_t n) const {
    const uint32_t w = written();
    return w >= n && copy(w - n, out, n);
  }

  // The next frame, if any (from loop()).
  bool frame(Frame &f) { return xQueueReceive(frames_, &f, 0) == pdTRUE; }

  // ---- The raw signal (S1) ---------------------------------------------------------------------

  // The slow average of the raw values: KY-037 0-4095 ADC steps, INMP441 24-bit units.
  float biasRaw() const { return dc_; }
  int biasMv() const { return digital() ? 0 : toMv(int(dc_)); }
  int toMv(int raw) const {
    if (digital()) return 0;
    int mv = 0;
    if (cali_ && adc_cali_raw_to_voltage(cali_, raw, &mv) == ESP_OK) return mv;
    return raw * attenTopMv(atten_) / 4095;  // no calibration in eFuse: a straight-line guess
  }
  // Lowest and highest raw value over the last ~100 ms: is the wave hitting the ends (clipping)?
  int rawLow() const { return rawLow_; }
  int rawHigh() const { return rawHigh_; }
  int rawMax() const { return digital() ? (1 << 23) - 1 : 4095; }
  bool clipping() const { return digital() ? (rawHigh_ >= rawMax() - 16 || rawLow_ <= -rawMax() + 16) : (rawLow_ <= 0 || rawHigh_ >= 4095); }
  bool calibrated() const { return cali_ != nullptr; }

  uint32_t overruns() const { return overruns_; }        // the DMA pool overflowed: samples lost
  uint32_t framesDropped() const { return dropped_; }    // loop() was too slow to take frames
  uint32_t measuredRate() const { return measuredRate_; }  // samples counted in the last second

  // ---- The comparator (KY-037's DO) ------------------------------------------------------------

  bool doHigh() const { return source_ == Source::Ky037 && digitalRead(PIN_MIC_DO) == HIGH; }
  uint32_t doRises() const { return doRises_; }
  uint32_t doLastRiseUs() const { return doLastRiseUs_; }

 private:
  static bool startI2s(i2s_chan_handle_t &rx, uint32_t rate) {
    i2s_chan_config_t cc = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_0, I2S_ROLE_MASTER);
    cc.dma_frame_num = 256;
    if (i2s_new_channel(&cc, nullptr, &rx) != ESP_OK) return log_e("Mic: no I2S channel"), false;
    // Philips I2S, 32-bit slots, mono: the INMP441 sends 24 bits, MSB first, in the left slot (L/R
    // pin to GND). The ESP32-S3 drives SCK at rate x 64 (2 slots x 32 bits) = 1.024 MHz at 16 kHz.
    i2s_std_config_t sc = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(rate),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_32BIT, I2S_SLOT_MODE_MONO),
        .gpio_cfg = {.mclk = I2S_GPIO_UNUSED, .bclk = gpio_num_t(PIN_I2S_MIC_SCK), .ws = gpio_num_t(PIN_I2S_MIC_WS),
                     .dout = I2S_GPIO_UNUSED, .din = gpio_num_t(PIN_I2S_MIC_SD), .invert_flags = {}},
    };
    if (i2s_channel_init_std_mode(rx, &sc) != ESP_OK || i2s_channel_enable(rx) != ESP_OK) {
      i2s_del_channel(rx);
      rx = nullptr;
      return log_e("Mic: I2S set-up failed"), false;
    }
    gpio_pulldown_en(gpio_num_t(PIN_I2S_MIC_SD));  // nothing wired = zeros, not noise
    return true;
  }

  bool startSource() {
    if (source_ == Source::Inmp441) {
      if (!startI2s(rx_, rate_)) return false;
      dcRate_ = 1.0f / 8192.0f;
      gain_ = 1.0f / float(1 << (kI2sShift - 8));
      log_i("Mic: INMP441 on I2S (SCK %d, WS %d, SD %d) at %lu Hz, 24-bit", PIN_I2S_MIC_SCK, PIN_I2S_MIC_WS, PIN_I2S_MIC_SD,
            static_cast<unsigned long>(rate_));
      return true;
    }
    if (adc_continuous_io_to_channel(PIN_MIC_AO, &unit_, &channel_) != ESP_OK || unit_ != ADC_UNIT_1)
      return log_e("Mic: GPIO %d is not an ADC1 pin (use GPIO 1-10)", PIN_MIC_AO), false;
    adc_continuous_handle_cfg_t hc = {};
    hc.max_store_buf_size = 4096;
    hc.conv_frame_size = 256 * SOC_ADC_DIGI_DATA_BYTES_PER_CONV;
    if (adc_continuous_new_handle(&hc, &adc_) != ESP_OK) return log_e("Mic: adc_continuous_new_handle failed"), false;

    adc_digi_pattern_config_t pattern = {};
    pattern.atten = atten_;
    pattern.channel = channel_;
    pattern.unit = unit_;
    pattern.bit_width = SOC_ADC_DIGI_MAX_BITWIDTH;
    adc_continuous_config_t cfg = {};
    cfg.pattern_num = 1;
    cfg.adc_pattern = &pattern;
    cfg.sample_freq_hz = rate_;
    cfg.conv_mode = ADC_CONV_SINGLE_UNIT_1;
    cfg.format = ADC_DIGI_OUTPUT_FORMAT_TYPE2;
    if (adc_continuous_config(adc_, &cfg) != ESP_OK) return log_e("Mic: adc_continuous_config failed (rate %lu?)", static_cast<unsigned long>(rate_)), false;

    adc_continuous_evt_cbs_t cbs = {};
    cbs.on_pool_ovf = onOverflow;
    adc_continuous_register_event_callbacks(adc_, &cbs, this);

    // Calibration: each chip's ADC is measured at the factory and the result burnt into eFuse.
    // The "curve fitting" scheme turns raw values into millivolts with it.
    adc_cali_curve_fitting_config_t cc = {};
    cc.unit_id = unit_;
    cc.chan = channel_;
    cc.atten = atten_;
    cc.bitwidth = ADC_BITWIDTH_12;
    if (adc_cali_create_scheme_curve_fitting(&cc, &cali_) != ESP_OK) cali_ = nullptr;

    if (adc_continuous_start(adc_) != ESP_OK) return log_e("Mic: adc_continuous_start failed"), false;
    dcRate_ = 1.0f / 4096.0f;  // ~0.25 s to follow the bias at 16 kHz
    gain_ = 16.0f;             // 12-bit steps -> 16-bit
    log_i("Mic: KY-037 AO on GPIO %d (ADC1 channel %d) at %lu Hz, attenuation %s; DO on GPIO %d", PIN_MIC_AO, int(channel_),
          static_cast<unsigned long>(rate_), attenName(atten_), PIN_MIC_DO);
    return true;
  }

  void stopSource() {
    if (rx_) i2s_channel_disable(rx_), i2s_del_channel(rx_), rx_ = nullptr;
    if (adc_) adc_continuous_stop(adc_), adc_continuous_deinit(adc_), adc_ = nullptr;
    if (cali_) adc_cali_delete_scheme_curve_fitting(cali_), cali_ = nullptr;
  }

  static bool IRAM_ATTR onOverflow(adc_continuous_handle_t, const adc_continuous_evt_data_t *, void *self) {
    auto *mic = static_cast<Mic *>(self);
    mic->overruns_ = mic->overruns_ + 1;
    return false;
  }

  static void IRAM_ATTR onDoEdge(void *arg) {
    auto *self = static_cast<Mic *>(arg);
    self->doRises_ = self->doRises_ + 1;
    self->doLastRiseUs_ = uint32_t(esp_timer_get_time());  // 32 bits: read in one go, wraps safely
  }

  static void task(void *arg) { static_cast<Mic *>(arg)->run(); }

  // One block of raw values from whichever source; 0 when nothing came.
  int readBlock(int32_t *out, int max) {
    if (source_ == Source::Inmp441) {
      size_t got = 0;
      if (!rx_ || i2s_channel_read(rx_, out, max * sizeof(int32_t), &got, 100) != ESP_OK) return 0;
      const int n = int(got / sizeof(int32_t));
      for (int i = 0; i < n; i++) out[i] >>= 8;  // 24 bits, sign kept
      return n;
    }
    uint32_t got = 0;
    if (!adc_ || adc_continuous_read(adc_, adcBuf_, sizeof(adcBuf_), &got, 100) != ESP_OK) return 0;
    int n = 0;
    for (uint32_t i = 0; i + SOC_ADC_DIGI_RESULT_BYTES <= got && n < max; i += SOC_ADC_DIGI_RESULT_BYTES) {
      const auto *d = reinterpret_cast<const adc_digi_output_data_t *>(&adcBuf_[i]);
      if (d->type2.channel == channel_) out[n++] = d->type2.data;
    }
    return n;
  }

  void run() {
    uint32_t windowStart = millis(), counted = 0;
    int low = INT32_MAX, high = INT32_MIN, lowHighCount = 0;
    float sumSq = 0;
    int peak = 0, inChunk = 0;
    bool primed = false;
    for (;;) {
      if (reconfigure_) {
        reconfigure_ = false;
        stopSource();
        rate_ = wantRate_;
        atten_ = wantAtten_;
        primed = false;
        if (!startSource()) log_e("Mic: could not restart");
      }
      const int n = readBlock(raw_, kBlock);
      if (n == 0) {
        if (!adc_ && !rx_) vTaskDelay(pdMS_TO_TICKS(100));
        continue;
      }
      uint32_t w = written_.load(std::memory_order_relaxed);
      for (int i = 0; i < n; i++) {
        const int raw = raw_[i];
        if (!primed) dc_ = raw, primed = true;
        dc_ += (raw - dc_) * dcRate_;
        low = raw < low ? raw : low;
        high = raw > high ? raw : high;
        float v = (raw - dc_) * gain_;
        v = v > 32767 ? 32767 : v < -32768 ? -32768 : v;
        const int16_t s = int16_t(v);
        ring_[w & kMask] = s;
        w++;
        sumSq += float(s) * s;
        const int a = s < 0 ? -s : s;
        peak = a > peak ? a : peak;
        if (++inChunk == kChunk) {
          const Frame f{w, sqrtf(sumSq / kChunk), int16_t(peak > 32767 ? 32767 : peak)};
          if (xQueueSend(frames_, &f, 0) != pdTRUE) dropped_ = dropped_ + 1;  // loop() fell 1 s behind
          sumSq = 0, peak = 0, inChunk = 0;
        }
        if (++lowHighCount >= int(rate_ / 10)) {
          rawLow_ = low;
          rawHigh_ = high;
          low = INT32_MAX, high = INT32_MIN, lowHighCount = 0;
        }
        counted++;
      }
      written_.store(w, std::memory_order_release);
      const uint32_t now = millis();
      if (now - windowStart >= 1000) measuredRate_ = counted * 1000 / (now - windowStart), counted = 0, windowStart = now;
    }
  }

  static constexpr int kBlock = 256;
  int16_t *ring_ = nullptr;
  QueueHandle_t frames_ = nullptr;
  TaskHandle_t task_ = nullptr;
  i2s_chan_handle_t rx_ = nullptr;
  adc_continuous_handle_t adc_ = nullptr;
  adc_cali_handle_t cali_ = nullptr;
  adc_unit_t unit_ = ADC_UNIT_1;
  adc_channel_t channel_ = ADC_CHANNEL_0;
  uint8_t adcBuf_[kBlock * SOC_ADC_DIGI_DATA_BYTES_PER_CONV];
  int32_t raw_[kBlock];
  Source source_ = Source::Ky037;
  uint32_t rate_ = 16000, wantRate_ = 16000;
  adc_atten_t atten_ = ADC_ATTEN_DB_12, wantAtten_ = ADC_ATTEN_DB_12;
  float dcRate_ = 1.0f / 4096.0f, gain_ = 16.0f;
  volatile bool reconfigure_ = false;
  std::atomic<uint32_t> written_{0};
  volatile float dc_ = 0;
  volatile int rawLow_ = 0, rawHigh_ = 0;
  volatile uint32_t overruns_ = 0, dropped_ = 0, measuredRate_ = 0;
  volatile uint32_t doRises_ = 0, doLastRiseUs_ = 0;
};

}  // namespace snd

// The one place that says which wire goes where.
// Change a number here (or pass -DPIN_xxx=N as a build flag) and every lesson follows.
//
// Pins to keep away from on the ESP32-S3-N16R8:
//   0, 3, 45, 46   strapping pins: they decide how the chip boots
//   19, 20         native USB D- / D+
//   26-32          wired to the flash chip
//   33-37          wired to the octal PSRAM (that's the "R8" in N16R8)
//   43, 44         UART0 TX / RX: the serial monitor on the "COM" port
#pragma once

// On-board addressable RGB LED (WS2812). Most N16R8 DevKitC clones use 48;
// v1.1 boards use 38. If lesson 01 shows no colour, try 38.
#ifndef PIN_RGB
#define PIN_RGB 48
#endif

// The BOOT button already on the board. It only matters at power-on (hold it to enter flash mode);
// once our program runs, GPIO 0 is a normal input. Pressed = LOW. Used from lesson 03b.
#ifndef PIN_BOOT_BTN
#define PIN_BOOT_BTN 0
#endif

// Lesson 03b: external push button. GPIO 5 -> one leg, the diagonally opposite leg -> GND.
// The internal pull-up makes the pin read HIGH when up and LOW when pressed.
#ifndef PIN_BUTTON
#define PIN_BUTTON 5
#endif

// Lesson 02: external LED. GPIO 4 -> 220-330 ohm resistor -> LED long leg (+), short leg (-) -> GND.
#ifndef PIN_LED
#define PIN_LED 4
#endif

// Lesson 03: 1.9" ST7789 SPI display. These are the S3's native SPI2 (FSPI) pins, the fastest route.
// Module label -> ESP32-S3 pin
#ifndef PIN_TFT_SCLK
#define PIN_TFT_SCLK 12  // SCL / SCK / CLK
#endif
#ifndef PIN_TFT_MOSI
#define PIN_TFT_MOSI 11  // SDA / MOSI / DIN
#endif
#ifndef PIN_TFT_CS
#define PIN_TFT_CS 10    // CS
#endif
#ifndef PIN_TFT_DC
#define PIN_TFT_DC 9     // DC / RS / A0
#endif
#ifndef PIN_TFT_RST
#define PIN_TFT_RST 8    // RES / RST
#endif
#ifndef PIN_TFT_BL
#define PIN_TFT_BL 7     // BLK / BL / LED (backlight)
#endif

// RFID track: the RC522 board (MFRC522 chip) on the S3's second SPI bus (SPI3), so it never shares
// wires or timing with the screen on SPI2. The four SPI pins sit side by side on the left header
// in the same order as the module's pins: SDA, SCK, MOSI, MISO.
// Module label -> ESP32-S3 pin. 3.3V only: the MFRC522 is not 5 V tolerant.
#ifndef PIN_RFID_SS
#define PIN_RFID_SS 15    // SDA (in SPI mode this is chip select, NSS)
#endif
#ifndef PIN_RFID_SCK
#define PIN_RFID_SCK 16   // SCK
#endif
#ifndef PIN_RFID_MOSI
#define PIN_RFID_MOSI 17  // MOSI
#endif
#ifndef PIN_RFID_MISO
#define PIN_RFID_MISO 18  // MISO
#endif
#ifndef PIN_RFID_RST
#define PIN_RFID_RST 14   // RST (low = hard power-down)
#endif
#ifndef PIN_RFID_IRQ
#define PIN_RFID_IRQ 13   // IRQ (optional: -1 = not wired, the lab then polls)
#endif

// Sound track: the KY-037 microphone module (electret capsule + LM393 comparator + a blue trim pot).
// Power it from 3V3, never 5 V: its AO and DO outputs swing up to its supply, and the ESP32-S3 pins
// take 3.3 V at most. Module label -> ESP32-S3 pin.
//   AO must be an ADC1 pin (GPIO 1-10): ADC2 is busy while Wi-Fi is on. 6 = ADC1 channel 5.
//   DO is the comparator's yes/no output: any digital pin.
#ifndef PIN_MIC_AO
#define PIN_MIC_AO 6   // AO (analog: the microphone's voltage)
#endif
#ifndef PIN_MIC_DO
#define PIN_MIC_DO 21  // DO (digital: high = louder than the pot's threshold)
#endif

// Sound track, digital: the INMP441 MEMS microphone (I2S, 24-bit). VDD -> 3V3, GND -> GND,
// L/R -> GND (we read the left slot). Three wires in a row on the right header.
#ifndef PIN_I2S_MIC_SCK
#define PIN_I2S_MIC_SCK 40  // SCK (bit clock)
#endif
#ifndef PIN_I2S_MIC_WS
#define PIN_I2S_MIC_WS 41   // WS (word select: left/right)
#endif
#ifndef PIN_I2S_MIC_SD
#define PIN_I2S_MIC_SD 42   // SD (the data)
#endif

// Sound track, out loud: the MAX98357A I2S amplifier + a 4 ohm speaker on its screw terminal.
// VIN -> 5V (louder; 3V3 works, quieter), GND -> GND, GAIN and SD unconnected (9 dB, mono mix).
#ifndef PIN_I2S_SPK_BCLK
#define PIN_I2S_SPK_BCLK 39  // BCLK
#endif
#ifndef PIN_I2S_SPK_LRC
#define PIN_I2S_SPK_LRC 38   // LRC (word select)
#endif
#ifndef PIN_I2S_SPK_DIN
#define PIN_I2S_SPK_DIN 47   // DIN (the data)
#endif

// Drawing pieces every sound lab shares (320 x 170, landscape):
//   header   the lab id + the view's name, view dots, and the ear: a live level bar, the
//            comparator's DO lamp, and a red REC dot whenever anything is being recorded
//   footer   the button hint on the left, the latest note on the right (fading after 6 s)
//   wave     samples as a waveform in a box, scaled to fit
//   meter    a horizontal level bar with the floor, peak hold and a limit mark
#pragma once

#include <Fonts/FreeSans9pt7b.h>
#include <Fonts/FreeSansBold24pt7b.h>
#include <Fonts/FreeSansBold9pt7b.h>
#include <math.h>

#include "color.h"
#include "frame_buffer.h"
#include "level.h"

namespace sv {

constexpr int kW = 320, kH = 170, kTop = 30, kBottom = kH - 12;
// The sound track's colour on the bench palette, plus one for "recording".
constexpr uint16_t kSound = rgb(255, 128, 200);
constexpr uint16_t kRec = rgb(255, 60, 60);
constexpr uint16_t kPanel = rgb(20, 28, 40);

inline int textWidth(FrameBuffer &fb, const char *s) {
  int16_t x1, y1;
  uint16_t w, h;
  fb.getTextBounds(s, 0, 0, &x1, &y1, &w, &h);
  return w;
}

inline void small(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(nullptr);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void bold(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

inline void big(FrameBuffer &fb, int x, int y, uint16_t c, const char *s) {
  fb.setFont(&FreeSansBold24pt7b);
  fb.setTextColor(c);
  fb.setCursor(x, y);
  fb.print(s);
}

// A label over a value, in a column.
inline void stat(FrameBuffer &fb, int x, int y, const char *label, const char *value, uint16_t c = pal::ink) {
  small(fb, x, y, pal::muted, label);
  bold(fb, x, y + 22, c, value);
}

// Green while calm, amber when loud, coral when very loud (dB above the quiet).
inline uint16_t levelColour(float above) { return above < 25 ? pal::teal : above < 40 ? pal::amber : pal::coral; }

// The ear in the header: 10 segments of level, then the DO lamp (KY-037) or a small "D" (the digital
// INMP441), sound waves while the speaker plays, and the REC dot.
inline void ear(FrameBuffer &fb, int x, int y, const snd::LevelReading &r, bool doHigh, bool rec, float t, bool digital, bool speaking) {
  const int lit = int(snd::meterFraction(r.above(), 50) * 10 + 0.5f);
  for (int i = 0; i < 10; i++) fb.fillRect(x + i * 4, y, 3, 10, i < lit ? levelColour(i * 5.0f) : pal::dim);
  if (digital) small(fb, x + 45, y + 2, pal::teal, "D");
  else fb.fillCircle(x + 48, y + 5, 3, doHigh ? pal::amber : pal::dim);
  if (speaking)
    for (int i = 0; i < 2; i++) fb.drawCircleHelper(x - 8 + i * 3, y + 5, 3 + i * 3, 0x2 | 0x4, kSound);
  if (rec && fmodf(t, 1.0f) < 0.6f) fb.fillCircle(x + 60, y + 5, 4, kRec);
}

inline void header(FrameBuffer &fb, const char *labId, const char *view, int index, int count, const snd::LevelReading &r, bool doHigh,
                   bool rec, float t, bool digital = false, bool speaking = false) {
  fb.setFont(&FreeSansBold9pt7b);
  fb.setTextColor(kSound);
  fb.setCursor(8, 18);
  fb.print(labId);
  fb.print(" ");
  fb.setFont(&FreeSans9pt7b);
  fb.setTextColor(pal::muted);
  fb.print(view);
  ear(fb, kW - 74, 10, r, doHigh, rec, t, digital, speaking);
  const int firstDot = kW - 92 - (count - 1) * 9;
  for (int i = 0; i < count; i++) fb.fillCircle(firstDot + i * 9, 15, 3, i == index ? pal::ink : pal::dim);
  fb.drawFastHLine(0, 28, kW, pal::dim);
}

enum class Note : uint8_t { Info, Good, Warn, Bad };

inline uint16_t noteColour(Note k) {
  switch (k) {
    case Note::Good: return pal::teal;
    case Note::Warn: return pal::amber;
    case Note::Bad: return pal::coral;
    default: return pal::muted;
  }
}

inline const char *noteMark(Note k) {
  switch (k) {
    case Note::Good: return "+";
    case Note::Warn: return "!";
    case Note::Bad: return "x";
    default: return "-";
  }
}

inline void footer(FrameBuffer &fb, const char *hint, const char *note, Note kind, uint32_t noteAgeMs) {
  fb.fillRect(0, kH - 11, kW, 11, pal::night);
  small(fb, 6, kH - 9, pal::muted, hint);
  if (!note || !note[0] || noteAgeMs > 6000) return;
  char right[30];
  strlcpy(right, note, sizeof(right));
  fb.setFont(nullptr);
  const uint16_t c = mix(noteColour(kind), pal::night, uint8_t(noteAgeMs > 4000 ? (noteAgeMs - 4000) * 200 / 2000 : 0));
  small(fb, kW - 6 - textWidth(fb, right), kH - 9, c, right);
}

// Samples as a waveform: one column per pixel, min..max of the samples that fall in it, so nothing
// is hidden between pixels. `scale` = how many int16 units half the box height shows.
inline void wave(FrameBuffer &fb, int x, int y, int w, int h, const int16_t *s, int n, float scale, uint16_t c) {
  const int mid = y + h / 2;
  fb.drawFastHLine(x, mid, w, pal::dim);
  if (n <= 0 || scale <= 0) return;
  const float k = (h / 2 - 1) / scale;
  for (int col = 0; col < w; col++) {
    const int a = col * n / w, b = std::max(a + 1, (col + 1) * n / w);
    int lo = 32767, hi = -32768;
    for (int i = a; i < b && i < n; i++) lo = std::min<int>(lo, s[i]), hi = std::max<int>(hi, s[i]);
    const int y0 = std::max(y, std::min(y + h - 1, mid - int(hi * k))), y1 = std::max(y, std::min(y + h - 1, mid - int(lo * k)));
    fb.drawFastVLine(x + col, y0, y1 - y0 + 1, c);
  }
}

// The biggest |sample| in a block, for auto-scaling a wave (never below `minScale`).
inline float autoScale(const int16_t *s, int n, float minScale = 256) {
  int m = 0;
  for (int i = 0; i < n; i++) m = std::max(m, std::abs(int(s[i])));
  return std::max(minScale, float(m) * 1.1f);
}

// A level bar: fill up to `above` dB (of rangeDb), the peak hold as a tick, an optional limit line.
inline void meter(FrameBuffer &fb, int x, int y, int w, int h, const snd::LevelReading &r, float rangeDb = 60, float limitDb = -1) {
  fb.fillRoundRect(x, y, w, h, 3, kPanel);
  const int fill = int(snd::meterFraction(r.above(), rangeDb) * (w - 2));
  // Coloured in zones, so the colour says how loud even without reading the number.
  for (int i = 0; i < fill; i += 3) fb.fillRect(x + 1 + i, y + 2, 2, h - 4, levelColour(float(i) / (w - 2) * rangeDb));
  const float peakAbove = r.peakDb - r.floorDb;
  const int px = x + 1 + int(snd::meterFraction(peakAbove, rangeDb) * (w - 2));
  fb.drawFastVLine(px, y, h, pal::ink);
  if (limitDb > 0) {
    const int lx = x + 1 + int(snd::meterFraction(limitDb, rangeDb) * (w - 2));
    for (int j = y - 3; j < y + h + 3; j += 2) fb.drawPixel(lx, j, pal::coral);
  }
}

}  // namespace sv

// The speaker: a MAX98357A I2S amplifier and a small 4 ohm speaker. The board sends numbers, the
// amplifier turns them into sound. No DAC, no analog wire: I2S carries 16-bit samples, the MAX98357A
// switches the speaker on and off very fast (class D) in proportion to each number.
//
// A task on core 0 renders 256 samples at a time (16 ms at 16 kHz) and hands them to the I2S DMA.
// i2s_channel_write() waits while the DMA is full, so the task runs exactly as fast as the speaker
// plays. What it mixes:
//   - a tone or a tune (synth.h Voice + Tune), queued from any task with tone() / tune()
//   - recorded samples (synth.h Player): play(), at any speed (pitch). The caller keeps the samples
//     alive until playing() turns false.
//   - a live stream (stream()): S8's voice effects push processed microphone samples here.
//
// Echo guard: the microphone hears the speaker. recentlyLoud() says whether anything audible left
// the speaker in the last few hundred ms, so the lab shell can stop the clap/knock detectors from
// hearing the board's own beeps.
//
// Nothing wired? Then the numbers go nowhere and nothing happens: every lab works without it.
#pragma once

#include <Arduino.h>
#include <driver/i2s_std.h>
#include <esp_heap_caps.h>
#include <freertos/FreeRTOS.h>
#include <freertos/queue.h>

#include <algorithm>
#include <atomic>

#include "pins.h"
#include "synth.h"

namespace snd {

class Speaker {
 public:
  static constexpr uint32_t kRate = 16000;
  static constexpr int kBlock = 256;

  bool begin() {
    i2s_chan_config_t cc = I2S_CHANNEL_DEFAULT_CONFIG(I2S_NUM_1, I2S_ROLE_MASTER);
    cc.dma_frame_num = kBlock;
    cc.auto_clear_after_cb = true;  // if we ever fall behind, the DMA plays silence, not the last block again
    if (i2s_new_channel(&cc, &tx_, nullptr) != ESP_OK) return log_e("Speaker: no I2S channel"), false;
    i2s_std_config_t sc = {
        .clk_cfg = I2S_STD_CLK_DEFAULT_CONFIG(kRate),
        .slot_cfg = I2S_STD_PHILIPS_SLOT_DEFAULT_CONFIG(I2S_DATA_BIT_WIDTH_16BIT, I2S_SLOT_MODE_STEREO),
        .gpio_cfg = {.mclk = I2S_GPIO_UNUSED, .bclk = gpio_num_t(PIN_I2S_SPK_BCLK), .ws = gpio_num_t(PIN_I2S_SPK_LRC),
                     .dout = gpio_num_t(PIN_I2S_SPK_DIN), .din = I2S_GPIO_UNUSED, .invert_flags = {}},
    };
    // Stereo, the same sample in left and right: the amplifier's (L+R)/2 mix (SD unconnected) plays it either way.
    if (i2s_channel_init_std_mode(tx_, &sc) != ESP_OK || i2s_channel_enable(tx_) != ESP_OK) return log_e("Speaker: I2S set-up failed"), false;
    cmds_ = xQueueCreate(24, sizeof(Cmd));
    streamBuf_ = static_cast<int16_t *>(heap_caps_calloc(kStream, sizeof(int16_t), MALLOC_CAP_SPIRAM));
    if (!cmds_ || !streamBuf_) return log_e("Speaker: no memory"), false;
    xTaskCreatePinnedToCore(task, "speaker", 4096, this, 4, nullptr, 0);
    log_i("Speaker: MAX98357A on I2S (BCLK %d, LRC %d, DIN %d) at %lu Hz", PIN_I2S_SPK_BCLK, PIN_I2S_SPK_LRC, PIN_I2S_SPK_DIN,
          static_cast<unsigned long>(kRate));
    return true;
  }

  // 0-100. Loudness grows with the square: 50 sounds about half as loud as 100.
  void setVolume(int v) { volume_ = v < 0 ? 0 : v > 100 ? 100 : v; }
  int volume() const { return volume_; }

  // ---- What to play (from any task) ------------------------------------------------------------

  void tone(float hz, uint32_t ms, syn::Wave wave = syn::Wave::Sine, float level = 0.8f) {
    Cmd c{Cmd::Tone};
    c.hz = hz, c.ms = float(ms), c.wave = wave, c.level = level;
    send(c);
  }
  // A melody in Tune's text format. The text must stay alive while it plays (string literals do).
  void tune(const char *text, int bpm = 140, syn::Wave wave = syn::Wave::Triangle) {
    Cmd c{Cmd::Tune};
    c.text = text, c.bpm = bpm, c.wave = wave;
    send(c);
  }
  // Recorded samples at `step` x speed. They must stay alive until playing() is false.
  void play(const int16_t *samples, uint32_t count, float step = 1.0f, float gain = 1.0f) {
    Cmd c{Cmd::Play};
    c.samples = samples, c.count = count, c.step = step, c.level = gain;
    playing_ = true;  // at once, so the caller's next playing() check already says yes
    send(c);
  }
  void stop() { send(Cmd{Cmd::Stop}); }

  bool busy() const { return busy_; }
  bool playing() const { return playing_; }
  float progress() const { return progress_; }
  // Was anything audible sent in the last `ms`? (the echo guard)
  bool recentlyLoud(uint32_t ms = 250) const { return millis() - lastLoudMs_ < ms; }
  // The loudest output sample of the last block, 0-1 (for a meter).
  float outputLevel() const { return outLevel_; }

  // ---- Live stream (S8) ------------------------------------------------------------------------

  // Push samples to play as soon as possible. Single producer (loop()), the speaker task consumes.
  // Returns how many fitted; the rest are dropped (the stream is ~0.5 s deep).
  uint32_t stream(const int16_t *s, uint32_t n) {
    const uint32_t w = sw_.load(std::memory_order_relaxed), r = sr_.load(std::memory_order_acquire);
    const uint32_t room = kStream - 1 - (w - r);
    if (n > room) n = room;
    for (uint32_t i = 0; i < n; i++) streamBuf_[(w + i) & (kStream - 1)] = s[i];
    sw_.store(w + n, std::memory_order_release);
    return n;
  }
  uint32_t streamQueued() const { return sw_.load(std::memory_order_acquire) - sr_.load(std::memory_order_acquire); }

 private:
  struct Cmd {
    enum Kind : uint8_t { Tone, Tune, Play, Stop } kind;
    syn::Wave wave = syn::Wave::Sine;
    float hz = 0, ms = 0, level = 1, step = 1;
    const char *text = nullptr;
    int bpm = 140;
    const int16_t *samples = nullptr;
    uint32_t count = 0;
  };
  static constexpr uint32_t kStream = 8192;

  void send(const Cmd &c) {
    if (cmds_ && xQueueSend(cmds_, &c, 0) != pdTRUE) log_w("Speaker: too many sounds queued");
  }

  static void task(void *arg) { static_cast<Speaker *>(arg)->run(); }

  void apply(const Cmd &c) {
    const syn::Envelope env;
    switch (c.kind) {
      case Cmd::Tone:
        tune_.set(nullptr, 0);
        voice_.start(c.hz, c.ms, c.wave, env, kRate, c.level);
        break;
      case Cmd::Tune:
        tune_.set(c.text, c.bpm);
        tuneWave_ = c.wave;
        voice_ = syn::Voice{};
        break;
      case Cmd::Play: player_.set(c.samples, c.count, c.step, c.level); break;
      case Cmd::Stop:
        tune_.set(nullptr, 0);
        voice_ = syn::Voice{};
        player_.stop();
        sr_.store(sw_.load(std::memory_order_acquire), std::memory_order_release);
        break;
    }
  }

  void run() {
    static int16_t out[kBlock * 2];  // left + right
    for (;;) {
      Cmd c;
      while (xQueueReceive(cmds_, &c, 0) == pdTRUE) apply(c);
      // The tune hands the voice its next note when the last one has finished.
      if (!voice_.active() && !tune_.done()) {
        float hz = 0, ms = 0;
        if (tune_.next(hz, ms)) {
          syn::Envelope env;
          env.releaseMs = std::min(90.0f, ms * 0.3f);
          voice_.start(hz, ms - env.releaseMs, tuneWave_, env, kRate, 0.7f);
        }
      }
      const float gain = (volume_ / 100.0f) * (volume_ / 100.0f) * 32000.0f;
      float peak = 0;
      const uint32_t w = sw_.load(std::memory_order_acquire);
      uint32_t r = sr_.load(std::memory_order_relaxed);
      for (int i = 0; i < kBlock; i++) {
        float v = voice_.next() + player_.next();
        if (r != w) v += streamBuf_[r++ & (kStream - 1)] / 32768.0f;
        v = syn::softClip(v);
        peak = std::max(peak, fabsf(v));
        out[2 * i] = out[2 * i + 1] = int16_t(v * gain);
      }
      sr_.store(r, std::memory_order_release);
      outLevel_ = peak;
      if (peak * gain > 300) lastLoudMs_ = millis();
      busy_ = voice_.active() || !tune_.done() || player_.active() || r != sw_.load(std::memory_order_acquire);
      playing_ = player_.active();
      progress_ = player_.progress();
      size_t done = 0;
      i2s_channel_write(tx_, out, sizeof(out), &done, portMAX_DELAY);  // waits for room: this is the clock
    }
  }

  i2s_chan_handle_t tx_ = nullptr;
  QueueHandle_t cmds_ = nullptr;
  syn::Voice voice_;
  syn::Tune tune_;
  syn::Wave tuneWave_ = syn::Wave::Triangle;
  syn::Player player_;
  int16_t *streamBuf_ = nullptr;
  std::atomic<uint32_t> sw_{0}, sr_{0};
  volatile int volume_ = 40;
  volatile bool busy_ = false, playing_ = false;
  volatile float progress_ = 0, outLevel_ = 0;
  volatile uint32_t lastLoudMs_ = 0;
};

}  // namespace snd

// Making sound from numbers: the pieces the speaker (speaker.h) mixes, 16 000 samples a second.
//
//   Voice    one note: an oscillator (sine, square, triangle, saw, noise) shaped by an envelope.
//            ADSR = attack (fade in), decay (fall to the sustain level), sustain (hold), release
//            (fade out). Without it every note starts and stops with a click.
//   Tune     a melody as text: "C5/8 E5/8 G5/4 r/8 C6/2." = note + octave, / length (4 = quarter,
//            8 = eighth), a dot makes it 1.5x longer, r = rest. Tempo in beats per minute.
//   Player   plays recorded samples, at any speed: step 1.5 plays 1.5x faster, so 1.5x higher
//            (the chipmunk). Between two samples it draws a straight line (linear interpolation).
//
// Everything works in floats from -1 to +1; the speaker turns them into 16-bit numbers at the end.
// Pure C++ (no Arduino): host-tested in kit/test/host/sound_synth_test.cpp.
#pragma once

#include <ctype.h>
#include <math.h>
#include <stdint.h>
#include <stdlib.h>
#include <strings.h>

namespace syn {

enum class Wave : uint8_t { Sine, Square, Triangle, Saw, Noise };

inline const char *waveName(Wave w) {
  switch (w) {
    case Wave::Square: return "square";
    case Wave::Triangle: return "triangle";
    case Wave::Saw: return "saw";
    case Wave::Noise: return "noise";
    default: return "sine";
  }
}

inline bool parseWave(const char *s, Wave &out) {
  static const char *const kNames[] = {"sine", "square", "triangle", "saw", "noise"};
  for (int i = 0; i < 5; i++)
    if (strcasecmp(s, kNames[i]) == 0) return out = Wave(i), true;
  return false;
}

// "A4" = 440 Hz, "C#5", "Bb3". 0 for a rest ("r") or anything we can't read.
inline float noteHz(const char *name, float a4 = 440.0f) {
  if (!name || !name[0]) return 0;
  static const int kSemis[] = {9, 11, 0, 2, 4, 5, 7};  // A B C D E F G from C
  const char letter = char(toupper(name[0]));
  if (letter < 'A' || letter > 'G') return 0;
  int semi = kSemis[letter - 'A'], i = 1;
  if (name[i] == '#') semi++, i++;
  else if (name[i] == 'b') semi--, i++;
  if (!isdigit(name[i])) return 0;
  const int octave = name[i] - '0';
  const int midi = (octave + 1) * 12 + semi;
  return a4 * powf(2.0f, (midi - 69) / 12.0f);
}

struct Envelope {
  float attackMs = 6, decayMs = 80, sustain = 0.65f, releaseMs = 90;
};

class Voice {
 public:
  void start(float hz, float durMs, Wave w, const Envelope &env, float rate, float level = 1.0f) {
    hz_ = hz, wave_ = w, env_ = env, rate_ = rate, level_ = level;
    phase_ = 0;
    t_ = 0;
    dur_ = durMs * rate / 1000.0f;
    active_ = hz > 0 || w == Wave::Noise;
    silentUntil_ = active_ ? 0 : dur_;  // a rest still takes its time
  }
  void release() { dur_ = t_; }
  bool active() const { return active_ || t_ < silentUntil_; }
  float hz() const { return hz_; }

  float next() {
    if (!active_) {
      t_++;
      return 0;
    }
    const float ms = t_ * 1000.0f / rate_;
    const float relMs = t_ > dur_ ? (t_ - dur_) * 1000.0f / rate_ : 0;
    float a;
    if (relMs > 0) a = sustainAt(dur_ * 1000.0f / rate_) * (1.0f - relMs / env_.releaseMs);
    else a = sustainAt(ms);
    if (relMs >= env_.releaseMs || (relMs > 0 && a <= 0)) {  // a = 0 at the very start is the attack, not the end
      active_ = false;
      return 0;
    }
    t_++;
    phase_ += hz_ / rate_;
    phase_ -= floorf(phase_);
    return osc() * a * level_;
  }

 private:
  // The envelope level `ms` into the note, before the release.
  float sustainAt(float ms) const {
    if (ms < env_.attackMs) return ms / env_.attackMs;
    if (ms < env_.attackMs + env_.decayMs) return 1.0f - (1.0f - env_.sustain) * (ms - env_.attackMs) / env_.decayMs;
    return env_.sustain;
  }

  float osc() {
    switch (wave_) {
      case Wave::Square: return phase_ < 0.5f ? 0.6f : -0.6f;  // squares sound twice as loud: tamed
      case Wave::Triangle: return phase_ < 0.5f ? 4 * phase_ - 1 : 3 - 4 * phase_;
      case Wave::Saw: return (2 * phase_ - 1) * 0.7f;
      case Wave::Noise: noise_ = noise_ * 1664525u + 1013904223u; return (int32_t(noise_) >> 8) / 8388608.0f * 0.5f;
      default: return sinf(6.2831853f * phase_);
    }
  }

  float hz_ = 0, rate_ = 16000, level_ = 1, phase_ = 0, t_ = 0, dur_ = 0, silentUntil_ = 0;
  Wave wave_ = Wave::Sine;
  Envelope env_;
  bool active_ = false;
  uint32_t noise_ = 22222;
};

// Reads "C5/8 E5/8 G5/4 r/8 C6/2." one note at a time.
class Tune {
 public:
  void set(const char *text, int bpm) {
    text_ = at_ = text;
    bpm_ = bpm > 0 ? bpm : 120;
  }
  bool done() const { return !at_ || !*at_; }

  // The next note: false at the end. hz = 0 for a rest. ms = how long it lasts.
  bool next(float &hz, float &ms) {
    if (!at_) return false;
    while (*at_ == ' ' || *at_ == ',') at_++;
    if (!*at_) return false;
    char name[6] = {};
    int n = 0;
    while (*at_ && *at_ != '/' && *at_ != ' ' && n < 5) name[n++] = *at_++;
    int len = 4;
    if (*at_ == '/') len = int(strtol(at_ + 1, const_cast<char **>(&at_), 10));
    if (len <= 0) len = 4;
    float beats = 4.0f / len;
    if (*at_ == '.') beats *= 1.5f, at_++;
    while (*at_ && *at_ != ' ') at_++;  // skip anything we don't understand
    hz = (name[0] == 'r' || name[0] == 'R') ? 0 : noteHz(name);
    ms = beats * 60000.0f / bpm_;
    return true;
  }

 private:
  const char *text_ = nullptr, *at_ = nullptr;
  int bpm_ = 120;
};

class Player {
 public:
  void set(const int16_t *samples, uint32_t count, float step = 1.0f, float gain = 1.0f) {
    s_ = samples, n_ = count, step_ = step, gain_ = gain, pos_ = 0;
  }
  void stop() { n_ = 0; }
  bool active() const { return s_ && pos_ + 1 < n_; }
  float progress() const { return n_ ? float(pos_) / n_ : 0; }

  float next() {
    if (!active()) return 0;
    const uint32_t i = uint32_t(pos_);
    const float frac = float(pos_ - i);
    const float v = s_[i] + (s_[i + 1] - s_[i]) * frac;
    pos_ += step_;
    return v / 32768.0f * gain_;
  }

 private:
  const int16_t *s_ = nullptr;
  uint32_t n_ = 0;
  double pos_ = 0;
  float step_ = 1, gain_ = 1;
};

// Keeps the sum of several sounds inside -1..+1 without the harsh edge of plain clipping.
inline float softClip(float x) { return x > 1 ? 1 : x < -1 ? -1 : x * (1.5f - 0.5f * x * x); }

